INSERT INTO `email_templates` (`id`, `template_key`, `subject`, `body`, `variables`, `description`, `created_at`, `updated_at`) VALUES
(1, 'welcome', 'ยินดีต้อนรับสู่ {app_name}', '<div style=\"font-family: Prompt, sans-serif; max-width: 600px; margin: 0 auto; padding: 20px;\">\r\n    <h2 style=\"color: #2563eb;\">ยินดีต้อนรับ {user_name}!</h2>\r\n    <p>บัญชีของคุณได้ถูกสร้างเรียบร้อยแล้ว</p>\r\n    <div style=\"background: #f3f4f6; padding: 15px; border-radius: 8px; margin: 20px 0;\">\r\n        <p><strong>ข้อมูลการเข้าสู่ระบบ:</strong></p>\r\n        <ul>\r\n            <li>อีเมล: {user_email}</li>\r\n            <li>บทบาท: {user_role}</li>\r\n        </ul>\r\n    </div>\r\n    <p>คุณสามารถเข้าสู่ระบบได้ที่: <a href=\"{login_url}\">{login_url}</a></p>\r\n    <hr style=\"margin: 20px 0; border: none; border-top: 1px solid #e5e7eb;\">\r\n    <p style=\"font-size: 0.875rem; color: #6b7280;\">อีเมลนี้ถูกส่งจาก {app_name}<br>ติดต่อเรา: {contact_email}</p>\r\n</div>', '[\"user_name\", \"user_email\", \"user_role\", \"app_name\", \"login_url\", \"contact_email\"]', 'อีเมลต้อนรับสำหรับผู้ใช้ใหม่', '2026-01-30 22:26:25', '2026-01-30 22:26:25'),
(2, 'password_reset', 'การเปลี่ยนรหัสผ่านของคุณ - {app_name}', '<div style=\"font-family: Prompt, sans-serif; max-width: 600px; margin: 0 auto; padding: 20px;\">\r\n    <h2 style=\"color: #2563eb;\">การเปลี่ยนรหัสผ่าน</h2>\r\n    <p>สวัสดี {user_name},</p>\r\n    <p>รหัสผ่านของคุณได้ถูกเปลี่ยนแปลงเรียบร้อยแล้ว</p>\r\n    <div style=\"background: #fef3c7; padding: 15px; border-radius: 8px; margin: 20px 0; border-left: 4px solid #f59e0b;\">\r\n        <p><strong>⚠️ หากคุณไม่ได้ทำการเปลี่ยนรหัสผ่าน</strong></p>\r\n        <p>กรุณาติดต่อผู้ดูแลระบบทันที</p>\r\n    </div>\r\n    <p>เวลาที่เปลี่ยน: {change_time}</p>\r\n    <hr style=\"margin: 20px 0; border: none; border-top: 1px solid #e5e7eb;\">\r\n    <p style=\"font-size: 0.875rem; color: #6b7280;\">ติดต่อเรา: {contact_email}</p>\r\n</div>', '[\"user_name\", \"change_time\", \"app_name\", \"contact_email\"]', 'ยืนยันการเปลี่ยนรหัสผ่าน', '2026-01-30 22:26:25', '2026-01-30 22:26:25'),
(3, 'account_status', 'การเปลี่ยนแปลงสถานะบัญชี - {app_name}', '<div style=\"font-family: Prompt, sans-serif; max-width: 600px; margin: 0 auto; padding: 20px;\">\r\n    <h2 style=\"color: #2563eb;\">การเปลี่ยนแปลงสถานะบัญชี</h2>\r\n    <p>สวัสดี {user_name},</p>\r\n    <p>สถานะบัญชีของคุณได้ถูกเปลี่ยนเป็น: <strong>{account_status}</strong></p>\r\n    <p>เหตุผล: {reason}</p>\r\n    <hr style=\"margin: 20px 0; border: none; border-top: 1px solid #e5e7eb;\">\r\n    <p style=\"font-size: 0.875rem; color: #6b7280;\">ติดต่อเรา: {contact_email}</p>\r\n</div>', '[\"user_name\", \"account_status\", \"reason\", \"app_name\", \"contact_email\"]', 'แจ้งเตือนการเปลี่ยนสถานะบัญชี', '2026-01-30 22:26:25', '2026-01-30 22:26:25'),
(4, 'assessment_open', 'เปิดรอบการประเมิน: {assessment_name}', '<div style=\"font-family: Prompt, sans-serif; max-width: 600px; margin: 0 auto; padding: 20px;\">\r\n    <h2 style=\"color: #10b981;\">🎯 เปิดรอบการประเมินใหม่</h2>\r\n    <p>สวัสดี {user_name},</p>\r\n    <p>รอบการประเมิน <strong>{assessment_name}</strong> ได้เปิดรับแล้ว</p>\r\n    <div style=\"background: #f0fdf4; padding: 15px; border-radius: 8px; margin: 20px 0;\">\r\n        <p><strong>รายละเอียด:</strong></p>\r\n        <ul>\r\n            <li>ชื่อรอบ: {assessment_name}</li>\r\n            <li>เปิดรับ: {start_date}</li>\r\n            <li>ปิดรับ: {end_date}</li>\r\n        </ul>\r\n    </div>\r\n    <p><a href=\"{assessment_url}\" style=\"background: #10b981; color: white; padding: 10px 20px; text-decoration: none; border-radius: 5px; display: inline-block;\">เริ่มการประเมิน</a></p>\r\n    <hr style=\"margin: 20px 0; border: none; border-top: 1px solid #e5e7eb;\">\r\n    <p style=\"font-size: 0.875rem; color: #6b7280;\">ติดต่อเรา: {contact_email}</p>\r\n</div>', '[\"user_name\", \"assessment_name\", \"start_date\", \"end_date\", \"assessment_url\", \"contact_email\"]', 'แจ้งเตือนเปิดรอบการประเมิน', '2026-01-30 22:26:25', '2026-01-30 22:26:25'),
(5, 'assessment_deadline', 'เตือน: ใกล้ถึงกำหนดส่งแบบประเมิน - {assessment_name}', '<div style=\"font-family: Prompt, sans-serif; max-width: 600px; margin: 0 auto; padding: 20px;\">\r\n    <h2 style=\"color: #f59e0b;\">⏰ เตือนกำหนดส่ง</h2>\r\n    <p>สวัสดี {user_name},</p>\r\n    <p>ใกล้ถึงกำหนดส่งแบบประเมิน <strong>{assessment_name}</strong> แล้ว</p>\r\n    <div style=\"background: #fef3c7; padding: 15px; border-radius: 8px; margin: 20px 0; border-left: 4px solid #f59e0b;\">\r\n        <p><strong>กำหนดส่ง: {deadline_date}</strong></p>\r\n        <p>เหลือเวลาอีก: {days_remaining} วัน</p>\r\n    </div>\r\n    <p><a href=\"{assessment_url}\" style=\"background: #f59e0b; color: white; padding: 10px 20px; text-decoration: none; border-radius: 5px; display: inline-block;\">ส่งแบบประเมิน</a></p>\r\n    <hr style=\"margin: 20px 0; border: none; border-top: 1px solid #e5e7eb;\">\r\n    <p style=\"font-size: 0.875rem; color: #6b7280;\">ติดต่อเรา: {contact_email}</p>\r\n</div>', '[\"user_name\", \"assessment_name\", \"deadline_date\", \"days_remaining\", \"assessment_url\", \"contact_email\"]', 'เตือนก่อนถึงกำหนดส่ง', '2026-01-30 22:26:25', '2026-01-30 22:26:25'),
(6, 'assessment_submitted', 'ยืนยันการรับแบบประเมิน - {assessment_name}', '<div style=\"font-family: Prompt, sans-serif; max-width: 600px; margin: 0 auto; padding: 20px;\">\r\n    <h2 style=\"color: #10b981;\">✅ รับแบบประเมินเรียบร้อย</h2>\r\n    <p>สวัสดี {user_name},</p>\r\n    <p>เราได้รับแบบประเมิน <strong>{assessment_name}</strong> ของคุณเรียบร้อยแล้ว</p>\r\n    <div style=\"background: #f0fdf4; padding: 15px; border-radius: 8px; margin: 20px 0;\">\r\n        <p><strong>ข้อมูลการส่ง:</strong></p>\r\n        <ul>\r\n            <li>เวลาที่ส่ง: {submit_time}</li>\r\n            <li>สถานะ: รอการตรวจสอบ</li>\r\n        </ul>\r\n    </div>\r\n    <p>ผลการประเมินจะแจ้งให้ทราบภายหลัง</p>\r\n    <hr style=\"margin: 20px 0; border: none; border-top: 1px solid #e5e7eb;\">\r\n    <p style=\"font-size: 0.875rem; color: #6b7280;\">ติดต่อเรา: {contact_email}</p>\r\n</div>', '[\"user_name\", \"assessment_name\", \"submit_time\", \"contact_email\"]', 'ยืนยันการรับแบบประเมิน', '2026-01-30 22:26:25', '2026-01-30 22:26:25'),
(7, 'assessment_results', 'ประกาศผลการประเมิน - {assessment_name}', '<div style=\"font-family: Prompt, sans-serif; max-width: 600px; margin: 0 auto; padding: 20px;\">\r\n    <h2 style=\"color: #2563eb;\">📊 ประกาศผลการประเมิน</h2>\r\n    <p>สวัสดี {user_name},</p>\r\n    <p>ผลการประเมิน <strong>{assessment_name}</strong> ของคุณออกแล้ว</p>\r\n    <div style=\"background: #eff6ff; padding: 15px; border-radius: 8px; margin: 20px 0;\">\r\n        <p><strong>คะแนนของคุณ: {score}</strong></p>\r\n        <p>ระดับ: {level}</p>\r\n    </div>\r\n    <p><a href=\"{results_url}\" style=\"background: #2563eb; color: white; padding: 10px 20px; text-decoration: none; border-radius: 5px; display: inline-block;\">ดูผลการประเมิน</a></p>\r\n    <hr style=\"margin: 20px 0; border: none; border-top: 1px solid #e5e7eb;\">\r\n    <p style=\"font-size: 0.875rem; color: #6b7280;\">ติดต่อเรา: {contact_email}</p>\r\n</div>', '[\"user_name\", \"assessment_name\", \"score\", \"level\", \"results_url\", \"contact_email\"]', 'แจ้งผลการประเมิน', '2026-01-30 22:26:25', '2026-01-30 22:26:25'),
(8, 'system_update', 'ประกาศอัปเดตระบบ - {app_name}', '<div style=\"font-family: Prompt, sans-serif; max-width: 600px; margin: 0 auto; padding: 20px;\">\r\n    <h2 style=\"color: #2563eb;\">🔔 ประกาศอัปเดตระบบ</h2>\r\n    <p>สวัสดี {user_name},</p>\r\n    <p><strong>{update_title}</strong></p>\r\n    <div style=\"background: #eff6ff; padding: 15px; border-radius: 8px; margin: 20px 0;\">\r\n        <p>{update_details}</p>\r\n    </div>\r\n    <p>วันที่อัปเดต: {update_date}</p>\r\n    <hr style=\"margin: 20px 0; border: none; border-top: 1px solid #e5e7eb;\">\r\n    <p style=\"font-size: 0.875rem; color: #6b7280;\">ติดต่อเรา: {contact_email}</p>\r\n</div>', '[\"user_name\", \"update_title\", \"update_details\", \"update_date\", \"app_name\", \"contact_email\"]', 'ประกาศอัปเดตระบบ', '2026-01-30 22:26:25', '2026-01-30 22:26:25'),
(9, 'maintenance', 'แจ้งปิดปรับปรุงระบบ - {app_name}', '<div style=\"font-family: Prompt, sans-serif; max-width: 600px; margin: 0 auto; padding: 20px;\">\r\n    <h2 style=\"color: #f59e0b;\">🔧 แจ้งปิดปรับปรุงระบบ</h2>\r\n    <p>สวัสดี {user_name},</p>\r\n    <p>ระบบจะปิดปรับปรุงชั่วคราว</p>\r\n    <div style=\"background: #fef3c7; padding: 15px; border-radius: 8px; margin: 20px 0; border-left: 4px solid #f59e0b;\">\r\n        <p><strong>ช่วงเวลา:</strong></p>\r\n        <ul>\r\n            <li>เริ่ม: {start_time}</li>\r\n            <li>สิ้นสุด: {end_time}</li>\r\n        </ul>\r\n        <p><strong>เหตุผล:</strong> {reason}</p>\r\n    </div>\r\n    <p>ขออภัยในความไม่สะดวก</p>\r\n    <hr style=\"margin: 20px 0; border: none; border-top: 1px solid #e5e7eb;\">\r\n    <p style=\"font-size: 0.875rem; color: #6b7280;\">ติดต่อเรา: {contact_email}</p>\r\n</div>', '[\"user_name\", \"start_time\", \"end_time\", \"reason\", \"app_name\", \"contact_email\"]', 'แจ้งปิดปรับปรุงระบบ', '2026-01-30 22:26:25', '2026-01-30 22:26:25'),
(10, 'new_assignment', 'แจ้งการมอบหมายแบบประเมินใหม่ - {app_name}', '<p>เรียน คุณ {auditor_name},</p>\r\n        <p>คุณได้รับมอบหมายให้ตรวจสอบแบบประเมินของ <strong>{company_name}</strong> ในรอบปี <strong>{year}</strong> ({period_name})</p>\r\n        <p>กรุณาคลิกที่ลิงก์ด้านล่างเพื่อเข้าสู่ระบบและตรวจสอบ:</p>\r\n        <p><a href=\"{view_url}\" style=\"display:inline-block; padding:10px 20px; background:#2563eb; color:white; border-radius:8px; text-decoration:none;\">ไปที่แบบประเมิน</a></p>\r\n        <p>ขอบคุณครับ,<br>{app_name}</p>', NULL, NULL, '2026-01-31 12:57:06', '2026-01-31 12:57:06');
INSERT INTO `hicm_expertise_tags` (`id`, `pillar_code`, `tag_code`, `name_th`, `name_en`, `description`, `display_order`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'H1', 'H1-HPD', 'การวางนโยบายและยุทธศาสตร์สุขภาพองค์กร', 'Health Policy Design', 'การออกแบบนโยบายสุขภาพระดับองค์กร การกำหนดวิสัยทัศน์และเป้าหมายด้านสุขภาพ', 1, 1, '2026-02-04 01:19:52', '2026-02-04 01:19:52'),
(2, 'H1', 'H1-HWP', 'การออกแบบโปรแกรมสุขภาพ 4 มิติ (กาย ใจ สังคม ปัญญา)', 'Holistic Wellness Program', 'โปรแกรมส่งเสริมสุขภาพแบบองค์รวมครอบคลุมทุกมิติ', 2, 1, '2026-02-04 01:19:52', '2026-02-04 01:19:52'),
(3, 'H1', 'H1-ONT', 'โภชนาการสำหรับวัยทำงาน', 'Occupational Nutrition', 'โภชนาการและอาหารที่เหมาะสมสำหรับพนักงาน โรงอาหาร อาหารกลางวัน', 3, 1, '2026-02-04 01:19:52', '2026-02-04 01:19:52'),
(4, 'H1', 'H1-HSS', 'การคัดกรองและเฝ้าระวังสุขภาพเชิงรุก', 'Health Screening & Surveillance', 'ระบบตรวจสุขภาพประจำปี การเฝ้าระวังโรคจากการทำงาน', 4, 1, '2026-02-04 01:19:52', '2026-02-04 01:19:52'),
(5, 'H1', 'H1-PER', 'การส่งเสริมสมรรถภาพทางกายและยุทธศาสตร์ลดพฤติกรรมเนือยนิ่ง', 'Physical Ergonomics', 'กิจกรรมออกกำลังกาย การปรับปรุงสถานที่ทำงานเพื่อลด Sedentary', 5, 1, '2026-02-04 01:19:52', '2026-02-04 01:19:52'),
(6, 'I2', 'I2-ISO', 'ผู้ตรวจประเมินมาตรฐานความปลอดภัยและสิ่งแวดล้อม', 'ISO 45001 / 14001 Auditor', 'ผู้ตรวจประเมินระบบจัดการอาชีวอนามัยและสิ่งแวดล้อมมาตรฐานสากล', 1, 1, '2026-02-04 01:19:52', '2026-02-04 01:19:52'),
(7, 'I2', 'I2-OHH', 'การจัดการสุขศาสตร์อุตสาหกรรม (ฝุ่น, เสียง, สารเคมี)', 'Occupational Health & Hygiene', 'การตรวจวัดและควบคุมสิ่งคุกคามสุขภาพในสถานที่ทำงาน', 2, 1, '2026-02-04 01:19:52', '2026-02-04 01:19:52'),
(8, 'I2', 'I2-IPC', 'การจัดการมลพิษในโรงงานและรอบสถานประกอบการ', 'Industrial Pollution Control', 'การจัดการน้ำเสีย อากาศ กากของเสีย และมลพิษอุตสาหกรรม', 3, 1, '2026-02-04 01:19:52', '2026-02-04 01:19:52'),
(9, 'I2', 'I2-PRA', 'การประเมินและบริหารจัดการความเสี่ยงเชิงรุก', 'Proactive Risk Assessment', 'การวิเคราะห์และประเมินความเสี่ยงด้านความปลอดภัยเชิงรุก', 4, 1, '2026-02-04 01:19:52', '2026-02-04 01:19:52'),
(10, 'I2', 'I2-EIM', 'การจัดการผลกระทบด้านสิ่งแวดล้อมและนิเวศอุตสาหกรรม', 'Environmental Impact Management', 'การจัดการผลกระทบต่อชุมชนและระบบนิเวศโดยรอบ', 5, 1, '2026-02-04 01:19:52', '2026-02-04 01:19:52'),
(11, 'C3', 'C3-CSR', 'การออกแบบกิจกรรมรับผิดชอบต่อสังคมที่มุ่งเน้นเรื่องสุขภาพ', 'CSR for Health', 'กิจกรรม CSR ที่เน้นการส่งเสริมสุขภาพชุมชน', 1, 1, '2026-02-04 01:19:52', '2026-02-04 01:19:52'),
(12, 'C3', 'C3-CRM', 'การจัดการความสัมพันธ์และสร้างความร่วมมือกับชุมชน', 'Community Relations Management', 'การสร้างความสัมพันธ์ที่ดีกับชุมชนรอบสถานประกอบการ', 2, 1, '2026-02-04 01:19:52', '2026-02-04 01:19:52'),
(13, 'C3', 'C3-STE', 'การจัดการผู้มีส่วนได้ส่วนเสียและภาคีเครือข่าย', 'Stakeholder Engagement', 'การประสานงานกับหน่วยงานและผู้มีส่วนได้ส่วนเสีย', 3, 1, '2026-02-04 01:19:52', '2026-02-04 01:19:52'),
(14, 'C3', 'C3-HLD', 'การพัฒนาผู้นำและแกนนำสุขภาพในชุมชน', 'Health Leadership Development', 'การสร้างและพัฒนาผู้นำด้านสุขภาพในชุมชน', 4, 1, '2026-02-04 01:19:52', '2026-02-04 01:19:52'),
(15, 'C3', 'C3-PPP', 'การประสานความร่วมมือระหว่างรัฐและเอกชน', 'Public-Private Partnership (PPP)', 'การทำงานร่วมกับภาครัฐในโครงการสุขภาพ', 5, 1, '2026-02-04 01:19:52', '2026-02-04 01:19:52'),
(16, 'M4', 'M4-SPV', 'การวางแผนยุทธศาสตร์ความยั่งยืนระยะยาว', 'Strategic Planning & Visioning', 'การวางแผนกลยุทธ์และวิสัยทัศน์องค์กรสุขภาพยั่งยืน', 1, 1, '2026-02-04 01:19:52', '2026-02-04 01:19:52'),
(17, 'M4', 'M4-IME', 'ระบบติดตามและประเมินผลแบบบูรณาการ', 'Integrated M&E', 'ระบบ Monitoring & Evaluation แบบบูรณาการ', 2, 1, '2026-02-04 01:19:52', '2026-02-04 01:19:52'),
(18, 'M4', 'M4-LOS', 'ผู้เชี่ยวชาญการสร้างองค์กรแห่งการเรียนรู้', 'Learning Organization Specialist', 'การพัฒนาองค์กรให้เป็นองค์กรแห่งการเรียนรู้', 3, 1, '2026-02-04 01:19:52', '2026-02-04 01:19:52'),
(19, 'M4', 'M4-DDM', 'การใช้ข้อมูลเชิงประจักษ์เพื่อการบริหารจัดการ', 'Data-Driven Management', 'การตัดสินใจบนฐานข้อมูลและหลักฐานเชิงประจักษ์', 4, 1, '2026-02-04 01:19:52', '2026-02-04 01:19:52'),
(20, 'M4', 'M4-SFR', 'การจัดการงบประมาณและทรัพยากรเพื่อความยั่งยืน', 'Sustainable Finance & Resource', 'การบริหารงบประมาณและทรัพยากรอย่างยั่งยืน', 5, 1, '2026-02-04 01:19:52', '2026-02-04 01:19:52');
INSERT INTO `indicators` (`id`, `pillar_id`, `code`, `name_th`, `name_en`, `description`, `criteria_0`, `criteria_025`, `criteria_05`, `criteria_075`, `criteria_1`, `criteria_na`, `allow_na`, `has_performance_report`, `has_evidence_file`, `max_score`, `display_order`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 1, 'H1.1', 'นโยบายสุขภาวะองค์กร', '(Organizational Health Policy)', 'สถานประกอบการมีนโยบายสุขภาวะองค์กร (สุขภาวะ = ความอยู่ดีมีสุขอย่างยั่งยืน ครอบคลุม 4 มิติ ได้แก่ กาย จิต สังคม และปัญญา)ที่ชัดเจน เป็นลายลักษณ์อักษร มีคำนิยาม/ขอบเขตสุขภาวะที่เฉพาะเจาะจง ลงนามโดยผู้บริหารสูงสุด ประกาศสื่อสารให้พนักงาน ผู้บริหาร และหน่วยงานทราบอย่างทั่วถึงผ่านช่องทางที่หลากหลาย และมีการทบทวนปรับปรุงอย่างน้อยปีละ 1 ครั้ง', 'ไม่มีนโยบายสุขภาวะเป็นลายลักษณ์อักษร', 'มีนโยบายสุขภาวะเป็นลายลักษณ์อักษร แต่ยังไม่มีการลงนามโดยผู้บริหารและยังไม่ประกาศอย่างเป็นทางการ', 'มีนโยบายสุขภาวะที่ลงนามโดยผู้บริหารสูงสุดและประกาศอย่างเป็นทางการ มีการแจ้งให้พนักงาน ผู้บริหาร และหน่วยงานรับทราบ', 'มีนโยบายสุขภาวะที่บูรณาการกับยุทธศาสตร์องค์กร มีการสื่อสารครบทุกช่องทาง (ป้ายประกาศ เว็บไซต์ ไลน์กลุ่ม ฯลฯ) และมีการทบทวนเป็นประจำ', 'มีนโยบายสุขภาวะที่ครอบคลุมครบ 4 มิติ บูรณาการกับยุทธศาสตร์องค์กร มีการสื่อสารทั่วถึงพร้อมหลักฐานการรับทราบ มีการทบทวนและปรับปรุงต่อเนื่อง และมีการวัดผลสัมฤทธิ์เป็นตัวเลขที่วัดผลได้ (เช่น % พนักงานรับทราบนโยบาย)', '', 0, 1, 1, 1.00, 1, 1, '2026-01-30 04:55:20', '2026-04-22 09:47:37'),
(2, 1, 'H1.2', 'แผนปฏิบัติการสุขภาวะประจำปี', '(Annual Health Action Plan)', 'สถานประกอบการมีแผนปฏิบัติการส่งเสริมสุขภาพประจำปีที่ชัดเจน มีกิจกรรมครอบคลุมสุขภาวะ 4 มิติ (กาย จิต สังคม ปัญญา) มีงบประมาณและผู้รับผิดชอบที่ชัดเจน มีการติดตามประเมินผลอย่างต่อเนื่อง และรายงานผลการดำเนินงานให้ผู้บริหารรับทราบอย่างน้อยทุก 3 เดือน', 'ไม่มีแผนปฏิบัติการด้านสุขภาวะ', 'มีการดำเนินการส่งเสริมสุขภาวะเบื้องต้นบางส่วน แต่ยังไม่มีแผนปฏิบัติการที่เป็นลายลักษณ์อักษรและไม่มีรายละเอียดครบถ้วน', 'มีแผนปฏิบัติการเป็นลายลักษณ์อักษร มีงบประมาณและผู้รับผิดชอบที่ชัดเจน มีการดำเนินงานตามแผน', 'มีแผนปฏิบัติการที่ชัดเจน ครอบคลุมสุขภาวะหลายมิติ มีงบประมาณ ผู้รับผิดชอบ และมีการติดตามผลแต่ยังไม่สม่ำเสมอ', 'มีแผนปฏิบัติการที่ชัดเจนครอบคลุมสุขภาวะ 4 มิติ มีงบประมาณและผู้รับผิดชอบ มีการติดตามผลอย่างต่อเนื่องสม่ำเสมอ รายงานผู้บริหารอย่างน้อยทุก 3 เดือน และมีการปรับปรุงแผนตามผลการดำเนินงาน', '', 0, 1, 1, 1.00, 2, 1, '2026-01-30 04:55:20', '2026-04-22 09:47:48'),
(3, 1, 'H1.3', 'ระบบข้อมูลสุขภาพพนักงาน', '(Employee Health Information System)', 'สถานประกอบการมีระบบฐานข้อมูลสุขภาพพนักงานที่ครบถ้วน ปลอดภัย สามารถวิเคราะห์ผลตรวจสุขภาพและแบ่งกลุ่มได้ (กลุ่มสุขภาพดี กลุ่มเสี่ยง กลุ่มป่วย) เพื่อนำไปวางแผนการส่งเสริมสุขภาพเชิงรุก โดยมีนโยบายรักษาความลับ (PDPA) และเคารพสิทธิ์ส่วนบุคคลของพนักงาน', 'ไม่มีระบบข้อมูลสุขภาพพนักงาน หรือมีแต่ไม่เป็นระบบ', 'มีการเก็บข้อมูลสุขภาพพื้นฐานบางส่วน แต่ยังไม่เป็นระบบ ไม่มีการวิเคราะห์หรือนำไปใช้ประโยชน์', 'มีการดำเนินการเป็นระบบ มีหลักฐานการใช้สิทธิประกันสังคม/ระบบตรวจสุขภาพ มีการรักษาความลับข้อมูล มีนโยบาย PDPA ขององค์กร', 'มีระบบฐานข้อมูลสุขภาพที่สามารถวิเคราะห์และออกรายงานสรุปได้ มีการอัปเดตข้อมูลประจำปี และมีการรักษาความลับตาม PDPA', 'มีระบบฐานข้อมูลวิเคราะห์ผลตรวจสุขภาพและแบ่งกลุ่มสุขภาพ (ดี/เสี่ยง/ป่วย) นำไปวางแผนการส่งเสริมสุขภาพเชิงกลุ่ม มีนโยบาย PDPA ขององค์กรที่ชัดเจน และสามารถติดตามผลลัพธ์สุขภาพรายปีได้', '', 0, 1, 1, 1.00, 3, 1, '2026-01-30 04:55:20', '2026-04-22 09:47:59'),
(4, 1, 'H1.4', 'การตรวจสุขภาพและติดตามผล', '(Health Examination and Follow-up)', 'สถานประกอบการจัดให้มีการตรวจสุขภาพประจำปีครบทุกกลุ่มตามกฎหมาย (100% ตามระเบียบบริษัท) มีการคัดกรอง NCDs และอาชีวอนามัยตามปัจจัยเสี่ยงของงาน มีระบบติดตามผลผู้ที่มีผลผิดปกติและผู้มีปัจจัยเสี่ยงอย่างต่อเนื่อง', 'ไม่มีการตรวจสุขภาพพนักงาน', 'มีการตรวจสุขภาพพนักงานบางส่วน แต่ยังไม่ครอบคลุมตามกฎหมาย', 'มีการตรวจสุขภาพครบทุกกลุ่มตามกฎหมาย มีรายงานผลการตรวจ', 'มีการตรวจสุขภาพครอบคลุมกลุ่มเสี่ยงและตามปัจจัยเสี่ยงของงาน มีการติดตามผลผู้ที่มีผลผิดปกติและผู้เสี่ยง', 'มีการตรวจสุขภาพครบถ้วน 100% ตามระเบียบบริษัท มีการจัดกลุ่มสุขภาพ (ดี/เสี่ยง/ป่วย) มีระบบติดตามผลต่อเนื่อง มีการวิเคราะห์แนวโน้มและวางแผนป้องกันเชิงรุกตามกลุ่มความเสี่ยง', '', 0, 1, 1, 1.00, 4, 1, '2026-01-30 04:55:20', '2026-04-22 09:48:10'),
(5, 1, 'H1.5', 'บริการให้คำปรึกษาและ EAP รวมการประเมินสุขภาพจิตและจิตสังคม', '(EAP &amp; Mental Health Assessment)', 'สถานประกอบการจัดให้มีบริการให้คำปรึกษาด้านสุขภาพจิต ปัญหาส่วนตัว และครอบครัว โดยมีช่องทางที่เข้าถึงง่ายและรักษาความลับ มีการประเมินสุขภาพจิตและปัจจัยเสี่ยงทางจิตสังคม มีการจัดระดับความเสี่ยง มีผู้เชี่ยวชาญคัดกรอง ให้คำปรึกษา และส่งต่อตามความเหมาะสม [รวม H1.5 + H1.7 เดิม ตามมติ Design Thinking]', 'ไม่มีบริการให้คำปรึกษาด้านสุขภาพจิต และไม่มีการประเมินสุขภาพจิต', 'มีแผนการดำเนินงานด้านสุขภาพจิต/EAP แต่ยังไม่ได้ดำเนินการจริง', 'มีแผนและระบบให้คำปรึกษา/EAP มีการดำเนินงานแต่ยังไม่ต่อเนื่อง มีช่องทางให้คำปรึกษาเบื้องต้น', 'มีแผนและระบบ EAP/สุขภาพจิตที่ครบถ้วน มีการดำเนินงานต่อเนื่อง มีผู้เชี่ยวชาญให้คำปรึกษา มีการประเมินและคัดกรองสุขภาพจิต', 'มีแผนและระบบ EAP/สุขภาพจิตครบวงจร มีการวิเคราะห์ความเสี่ยงทางจิตสังคม จัดระดับความเสี่ยง ดำเนินงาน ส่งเสริมสุขภาพจิต และส่งต่อตามความเสี่ยงอย่างเป็นระบบ มีการประเมินผลและพัฒนาอย่างต่อเนื่อง', '', 0, 1, 1, 1.00, 5, 1, '2026-01-30 04:55:20', '2026-04-22 09:48:25'),
(6, 1, 'H1.6', 'โครงการป้องกัน NCDs', '(Non-Communicable Diseases Prevention)', 'สถานประกอบการมีการดำเนินงานด้านโครงการป้องกันโรคไม่ติดต่อเรื้อรัง (NCDs) ได้แก่ เบาหวาน ความดันโลหิตสูง โรคหัวใจ มะเร็ง อ้วน ฯลฯ อย่างเป็นระบบและครบถ้วน', 'ไม่มีการดำเนินงานด้านการป้องกัน NCDs', 'มีการดำเนินงานด้าน NCDs เบื้องต้นบางส่วน แต่ยังไม่เป็นระบบ', 'มีการดำเนินงานที่เป็นระบบ มีหลักฐานประกอบ เช่น กิจกรรมคัดกรอง ให้ความรู้', 'มีการดำเนินงานครอบคลุม มีระบบติดตามกลุ่มเสี่ยง NCDs และประเมินผลการดำเนินงาน', 'มีการดำเนินงานครบถ้วนและมีประสิทธิภาพสูง มีผลลัพธ์ที่วัดได้ (เช่น % ลดปัจจัยเสี่ยง) และมีการพัฒนาโครงการอย่างยั่งยืน', '', 0, 1, 1, 1.00, 6, 1, '2026-01-30 04:55:20', '2026-04-22 09:48:37'),
(7, 1, 'H1.7', 'โครงการส่งเสริมการลดละเลิกบุหรี่และแอลกอฮอล์', '(Tobacco &amp; Alcohol Cessation Program)', 'สถานประกอบการมีการดำเนินงานโครงการส่งเสริมการลดละเลิกบุหรี่และแอลกอฮอล์ในที่ทำงาน อย่างเป็นระบบ ครบถ้วน และมีผลลัพธ์ที่วัดได้', 'ไม่มีการดำเนินงานด้านการลดละเลิกบุหรี่และแอลกอฮอล์', 'มีการดำเนินงานเบื้องต้น เช่น ป้ายรณรงค์ แต่ยังไม่เป็นระบบโครงการ', 'มีโครงการที่เป็นระบบ มีหลักฐานการดำเนินงาน มีกิจกรรมรณรงค์และให้ความรู้', 'มีโครงการที่ครอบคลุม มีระบบติดตามผู้เข้าร่วมโครงการ มีการประเมินผลการดำเนินงาน', 'มีโครงการที่ครบถ้วนและมีประสิทธิภาพสูง มีผลลัพธ์ที่วัดได้ (เช่น % ผู้เลิกบุหรี่สำเร็จ) มีความยั่งยืน', '', 0, 1, 1, 1.00, 7, 1, '2026-01-30 04:55:20', '2026-04-22 09:48:48'),
(8, 1, 'H1.8', 'กิจกรรมส่งเสริมสุขภาพ 4 มิติ', '(Holistic Health Promotion Activities)', 'สถานประกอบการมีการดำเนินงานกิจกรรมส่งเสริมสุขภาพแบบองค์รวม 4 มิติ ได้แก่ มิติกาย (Physical) เช่น การออกกำลังกาย มิติจิต (Mental) เช่น การจัดการความเครียด มิติสังคม (Social) เช่น กิจกรรมสัมพันธ์ และมิติปัญญา (Spiritual) เช่น การเรียนรู้และพัฒนาตนเอง', 'ไม่มีการดำเนินงานกิจกรรมส่งเสริมสุขภาพ 4 มิติ', 'มีกิจกรรมส่งเสริมสุขภาพบางส่วน แต่ครอบคลุมเพียงมิติเดียวและยังไม่เป็นระบบ', 'มีการดำเนินงานที่เป็นระบบครอบคลุม 2–3 มิติ มีหลักฐานประกอบ', 'มีการดำเนินงานครอบคลุมทั้ง 4 มิติ มีระบบติดตามการเข้าร่วมกิจกรรมและประเมินผล', 'มีการดำเนินงานครบถ้วนทั้ง 4 มิติ มีประสิทธิภาพสูง มีผลลัพธ์ที่วัดได้ (เช่น % พนักงานเข้าร่วม % ความพึงพอใจ) และมีการพัฒนากิจกรรมอย่างต่อเนื่อง', '', 0, 1, 1, 1.00, 8, 1, '2026-01-30 04:55:20', '2026-04-22 09:49:00'),
(9, 1, 'H1.9', 'แกนนำสุขภาพองค์กร', '(Health Champions Network)', 'สถานประกอบการมีการพัฒนาและบริหารเครือข่ายแกนนำสุขภาพในองค์กร เพื่อเป็นผู้นำการเปลี่ยนแปลงด้านสุขภาพในทุกหน่วยงาน', 'ไม่มีระบบแกนนำสุขภาพหรือการดำเนินงาน', 'มีการแต่งตั้งแกนนำสุขภาพเบื้องต้น แต่ยังไม่มีการพัฒนาศักยภาพหรือบทบาทที่ชัดเจน', 'มีระบบแกนนำสุขภาพที่เป็นระบบ มีการอบรมพัฒนาศักยภาพ มีบทบาทหน้าที่ชัดเจน', 'มีเครือข่ายแกนนำสุขภาพที่ครอบคลุมทุกหน่วยงาน มีการติดตามผลการดำเนินงาน มีการพัฒนาอย่างต่อเนื่อง', 'มีเครือข่ายแกนนำสุขภาพที่เข้มแข็ง ครอบคลุมทุกหน่วยงาน มีผลลัพธ์ที่วัดได้ เป็นกลไกสำคัญในการขับเคลื่อนสุขภาวะองค์กร มีการยกย่องเชิดชูและพัฒนาอย่างต่อเนื่อง', '', 0, 1, 1, 1.00, 9, 1, '2026-01-30 04:55:20', '2026-04-22 09:49:12'),
(10, 1, 'H1.10', 'โภชนาการในที่ทำงาน', '(Nutrition at Workplace)', 'สถานประกอบการมีการดำเนินงานด้านการส่งเสริมโภชนาการที่ดีในที่ทำงาน ทั้งการจัดสภาพแวดล้อมที่เอื้อต่อการกินอาหารที่ดีต่อสุขภาพ และการให้ความรู้ด้านโภชนาการแก่พนักงาน', 'ไม่มีการดำเนินงานด้านโภชนาการในที่ทำงาน', 'มีการดำเนินงานเบื้องต้น เช่น จัดป้ายให้ความรู้โภชนาการ แต่ยังไม่เป็นระบบ', 'มีการดำเนินงานที่เป็นระบบ มีหลักฐานประกอบ เช่น เมนูอาหารสุขภาพ กิจกรรมให้ความรู้', 'มีการดำเนินงานครอบคลุม มีการปรับสภาพแวดล้อมและเมนูอาหาร มีระบบติดตามและประเมินผล', 'มีการดำเนินงานครบถ้วนและมีประสิทธิภาพสูง มีผลลัพธ์ที่วัดได้ด้านพฤติกรรมการบริโภค พัฒนาอย่างยั่งยืน', '', 0, 1, 1, 1.00, 10, 1, '2026-01-30 04:55:20', '2026-04-22 09:49:27'),
(11, 1, 'H1.11', 'การออกกำลังกายในองค์กร', '(Physical Activity Program)', 'สถานประกอบการมีการส่งเสริมกิจกรรมทางกาย (Physical Activity) และการออกกำลังกายของพนักงานอย่างเป็นระบบ ทั้งในรูปแบบโครงการและการจัดสภาพแวดล้อมที่เอื้อต่อการออกกำลังกาย', 'ไม่มีการส่งเสริมการออกกำลังกายในองค์กร', 'มีการส่งเสริมการออกกำลังกายเบื้องต้น เช่น การบริหารร่างกายช่วงเช้า แต่ยังไม่เป็นระบบโครงการ', 'มีโครงการส่งเสริมการออกกำลังกายที่เป็นระบบ มีกิจกรรมสม่ำเสมอ มีหลักฐานการดำเนินงาน', 'มีโครงการที่ครอบคลุม มีการจัดสิ่งอำนวยความสะดวก มีระบบติดตามและประเมินผลการเข้าร่วม', 'มีโครงการส่งเสริมการออกกำลังกายที่ครบถ้วน มีผลลัพธ์ที่วัดได้ (% เข้าร่วม ระดับกิจกรรมทางกาย) มีการพัฒนาอย่างยั่งยืน', '', 0, 1, 1, 1.00, 11, 1, '2026-01-30 04:55:20', '2026-04-22 09:49:47'),
(12, 1, 'H1.12', 'สิทธิประโยชน์ด้านสุขภาพ', '(Health Benefits and Welfare)', 'สถานประกอบการมีการจัดสิทธิประโยชน์ด้านสุขภาพให้แก่พนักงานที่เหมาะสมและเพียงพอ ทั้งตามที่กฎหมายกำหนดและสิทธิเพิ่มเติมจากองค์กร', 'ไม่มีการจัดสิทธิประโยชน์ด้านสุขภาพนอกเหนือจากกฎหมายขั้นต่ำ', 'มีสิทธิประโยชน์ด้านสุขภาพขั้นพื้นฐานตามกฎหมาย แต่ยังไม่มีสิทธิเพิ่มเติม', 'มีสิทธิประโยชน์ด้านสุขภาพที่เป็นระบบ มีสิทธิเพิ่มเติมจากองค์กร มีการสื่อสารให้พนักงานรับทราบ', 'มีสิทธิประโยชน์ด้านสุขภาพที่ครอบคลุมและเหมาะสม มีระบบการรับสิทธิที่สะดวก มีการติดตามการใช้สิทธิ', 'มีสิทธิประโยชน์ด้านสุขภาพที่ครบถ้วนและมีคุณภาพสูง มีผลลัพธ์ที่วัดได้ (% การใช้สิทธิ) พัฒนาอย่างต่อเนื่องตามความต้องการพนักงาน', '', 0, 1, 1, 1.00, 12, 1, '2026-01-30 04:55:20', '2026-04-22 09:50:02'),
(13, 1, 'H1.13', 'การสื่อสารสุขภาพภายในองค์กร', '(Internal Health Communication)', 'สถานประกอบการมีระบบและช่องทางการสื่อสารด้านสุขภาพภายในองค์กรที่หลากหลาย ครอบคลุมทุกกลุ่มพนักงาน มีการสื่อสารสม่ำเสมอ และสามารถวัดผลการรับรู้ได้', 'ไม่มีการสื่อสารด้านสุขภาพภายในองค์กร', 'มีการสื่อสารด้านสุขภาพเบื้องต้น เช่น ป้ายประกาศ แต่ยังไม่เป็นระบบ', 'มีระบบการสื่อสารสุขภาพที่เป็นระบบผ่านหลายช่องทาง มีการสื่อสารสม่ำเสมอ มีหลักฐานประกอบ', 'มีการสื่อสารสุขภาพครอบคลุมทุกช่องทาง ถึงพนักงานทุกกลุ่ม มีระบบติดตามการรับรู้และประเมินผล', 'มีการสื่อสารสุขภาพที่ครอบคลุม ทั่วถึง มีประสิทธิภาพสูง มีผลลัพธ์ที่วัดได้ (% การรับรู้) พัฒนาช่องทางอย่างต่อเนื่อง', '', 0, 1, 1, 1.00, 13, 1, '2026-01-30 04:55:20', '2026-04-22 09:50:40'),
(14, 1, 'H1.14', 'การสรุปประเมินผลและทบทวนการดำเนินการด้านสุขภาวะองค์กร', '(Organizational Health Assessment Review)', 'สถานประกอบการมีการสรุปประเมินผลการดำเนินการด้านสุขภาวะองค์กรอย่างเป็นระบบ มีการทบทวนผลลัพธ์ วิเคราะห์จุดแข็ง-จุดอ่อน และวางแผนพัฒนาต่อเนื่อง [ปรับจาก H1.15 งานวิจัย ตามมติ Design Thinking]', 'ไม่มีการสรุปประเมินผลการดำเนินการด้านสุขภาวะองค์กร', 'มีการสรุปผลการดำเนินงานบางส่วน แต่ยังไม่เป็นระบบ ไม่ครบถ้วน', 'มีการสรุปประเมินผลที่เป็นระบบ มีหลักฐานประกอบ มีการรายงานผู้บริหาร', 'มีการสรุปประเมินผลครอบคลุมสุขภาวะ 4 มิติ มีการวิเคราะห์จุดแข็ง-จุดอ่อน มีระบบติดตามและทบทวนอย่างสม่ำเสมอ', 'มีการสรุปประเมินผลการดำเนินการด้านสุขภาวะองค์กรอย่างครบถ้วน มีการวิเคราะห์เปรียบเทียบกับปีก่อน มีการนำผลไปวางแผนพัฒนาและมีผลลัพธ์ที่ดีขึ้นอย่างต่อเนื่อง', '', 0, 1, 1, 1.00, 14, 1, '2026-01-30 04:55:20', '2026-04-22 09:50:57'),
(15, 1, 'H1.15', 'การออกแบบสภาพแวดล้อมและนวัตกรรมส่งเสริมสุขภาพ', '(Healthy Environment Design &amp; Health Innovation)', 'สถานประกอบการมีการออกแบบและปรับสภาพแวดล้อมทางกายภาพและสังคมในที่ทำงานให้เอื้อต่อสุขภาพ (Healthy Workplace Design) รวมถึงการนำนวัตกรรมและเทคโนโลยีมาใช้ในการส่งเสริมสุขภาพ [ตัวชี้วัดใหม่ตามมติ Design Thinking กลุ่ม 1]', 'ไม่มีการออกแบบสภาพแวดล้อมหรือนวัตกรรมส่งเสริมสุขภาพ', 'มีการปรับสภาพแวดล้อมเบื้องต้น เช่น มุมออกกำลังกาย แต่ยังไม่เป็นระบบ', 'มีการออกแบบสภาพแวดล้อมที่เป็นระบบ มีสิ่งอำนวยความสะดวกด้านสุขภาพ มีหลักฐานประกอบ', 'มีการออกแบบสภาพแวดล้อมที่ครอบคลุม มีการใช้นวัตกรรม/เทคโนโลยีสุขภาพ มีการประเมินผลการใช้งาน', 'มีการออกแบบสภาพแวดล้อมและใช้นวัตกรรมสุขภาพอย่างครบถ้วน มีผลลัพธ์ที่วัดได้ต่อพฤติกรรมสุขภาพพนักงาน พัฒนาอย่างต่อเนื่อง', '', 0, 1, 1, 1.00, 15, 1, '2026-01-30 04:55:20', '2026-04-22 09:51:15'),
(16, 2, 'I2.1', 'นโยบายความปลอดภัยและสิ่งแวดล้อม', '(OHS &amp; Environment Policy)', 'สถานประกอบการมีนโยบายความปลอดภัย อาชีวอนามัย และสิ่งแวดล้อมที่เป็นลายลักษณ์อักษร สอดคล้องกับบริบทองค์กร ลงนามโดย CEO เผยแพร่ทั่วทั้งองค์กร และมีการทบทวนต่อเนื่อง [ปรับปรุงตาม Design Thinking กลุ่ม 2]', 'ไม่มีนโยบาย OHS &amp; Environment เป็นลายลักษณ์อักษร', 'มีนโยบายเบื้องต้น แต่ยังไม่ลงนามโดย CEO และยังไม่เผยแพร่อย่างเป็นทางการ', 'มีนโยบาย OHS &amp; Environment ที่ลงนามโดย CEO ประกาศเผยแพร่ให้พนักงานทราบ ปฏิบัติตามกฎหมายขั้นพื้นฐาน', 'มีนโยบายครบถ้วน สอดคล้องบริบทองค์กร มีการสื่อสารทั่วถึง มีการทบทวนประจำปีและปรับปรุงตามผล', 'มีนโยบายที่เป็นเลิศ บูรณาการกับยุทธศาสตร์องค์กรและ ESG มีการวัดผลสัมฤทธิ์ของนโยบาย มีการพัฒนาต่อเนื่อง', '', 1, 1, 1, 1.00, 1, 1, '2026-01-30 04:55:57', '2026-04-22 10:09:11'),
(17, 2, 'I2.2', 'ระบบ HIRARC (การระบุอันตรายและประเมินความเสี่ยง)', '(Hazard Identification, Risk Assessment &amp; Risk Control)', 'สถานประกอบการมีระบบการระบุอันตราย ประเมินความเสี่ยง และควบคุมความเสี่ยง (HIRARC) อย่างครบถ้วนและเป็นปัจจุบัน ครอบคลุมทุกพื้นที่และกิจกรรมการทำงาน', 'ไม่มีระบบHIRARCหรือการดำเนินงาน', 'มีระบบHIRARCเบื้องต้น แต่ยังไม่ครบถ้วนตามกฎหมาย', 'มีระบบและปฏิบัติตามกฎหมายขั้นพื้นฐาน มีหลักฐานการดำเนินงาน', 'มีระบบHIRARCครบถ้วน มีการติดตามและปรับปรุงสม่ำเสมอ', 'มีระบบHIRARCที่เป็นเลิศ เป็นไปตามมาตรฐานสากล มีการพัฒนาต่อเนื่อง มีผลลัพธ์ที่วัดได้', '', 1, 1, 1, 1.00, 2, 1, '2026-01-30 04:55:57', '2026-04-22 10:10:31'),
(18, 2, 'I2.3', 'การป้องกัน รายงาน วิเคราะห์ สอบสวนอุบัติเหตุและโรคจากการทำงาน', '(Accident &amp; Occupational Disease Prevention, Reporting &amp; Investigation)', 'สถานประกอบการมีระบบการป้องกัน รายงาน วิเคราะห์ และสอบสวนอุบัติเหตุและโรคจากการทำงานอย่างเป็นระบบ โดยเน้นการวิเคราะห์สาเหตุรากเหง้า (Root Cause Analysis) เพื่อป้องกันไม่ให้เกิดซ้ำ [ปรับชื่อตาม Design Thinking กลุ่ม 2]', 'ไม่มีระบบรายงานหรือสอบสวนอุบัติเหตุ', 'มีการรายงานอุบัติเหตุเบื้องต้น แต่ยังไม่ครบถ้วนตามกฎหมาย', 'มีระบบรายงานอุบัติเหตุตามกฎหมาย มีการบันทึกและรายงานสถิติ', 'มีระบบสอบสวนอุบัติเหตุ มีการวิเคราะห์สาเหตุ มีมาตรการป้องกันและติดตามผล', 'มีระบบที่เป็นเลิศ มีการวิเคราะห์ Root Cause Analysis ทุกครั้ง มีการป้องกันเชิงรุก Zero Accident Culture มีผลลัพธ์วัดได้ (TRIR/LTIFR)', '', 0, 1, 1, 1.00, 3, 1, '2026-01-30 04:55:57', '2026-04-22 10:11:57'),
(19, 2, 'I2.4', 'อุปกรณ์ป้องกันอันตรายส่วนบุคคล (PPE)', '(Personal Protective Equipment)', 'สถานประกอบการมีระบบการจัดหา จ่าย บำรุงรักษา และฝึกอบรมการใช้ PPE ที่เหมาะสมกับความเสี่ยงของงานแต่ละประเภท', 'ไม่มีระบบPPEหรือการดำเนินงาน', 'มีระบบPPEเบื้องต้น แต่ยังไม่ครบถ้วนตามกฎหมาย', 'มีระบบและปฏิบัติตามกฎหมายขั้นพื้นฐาน มีหลักฐานการดำเนินงาน', 'มีระบบPPEครบถ้วน มีการติดตามและปรับปรุงสม่ำเสมอ', 'มีระบบPPEที่เป็นเลิศ เป็นไปตามมาตรฐานสากล มีการพัฒนาต่อเนื่อง มีผลลัพธ์ที่วัดได้', '', 0, 1, 1, 1.00, 4, 1, '2026-01-30 04:55:57', '2026-04-22 10:13:08'),
(20, 2, 'I2.5', 'การตรวจวัดสภาพแวดล้อมการทำงาน', '(Workplace Environment Monitoring)', 'สถานประกอบการมีการตรวจวัดสภาพแวดล้อมการทำงาน (Environmental Health Monitoring) ครอบคลุมความร้อน แสงสว่าง เสียง สารเคมี ฝุ่น ฯลฯ ตามกฎหมายและมาตรฐาน', 'ไม่มีระบบการตรวจวัดสภาพแวดล้อมหรือการดำเนินงาน', 'มีระบบการตรวจวัดสภาพแวดล้อมเบื้องต้น แต่ยังไม่ครบถ้วนตามกฎหมาย', 'มีระบบและปฏิบัติตามกฎหมายขั้นพื้นฐาน มีหลักฐานการดำเนินงาน', 'มีระบบการตรวจวัดสภาพแวดล้อมครบถ้วน มีการติดตามและปรับปรุงสม่ำเสมอ', 'มีระบบการตรวจวัดสภาพแวดล้อมที่เป็นเลิศ เป็นไปตามมาตรฐานสากล มีการพัฒนาต่อเนื่อง มีผลลัพธ์ที่วัดได้', '', 0, 1, 1, 1.00, 5, 1, '2026-01-30 04:55:57', '2026-04-22 10:15:30'),
(21, 2, 'I2.6', 'ระบบบริหารจัดการสารเคมีอันตราย', '(Hazardous Chemical Management System)', 'สถานประกอบการมีระบบบริหารจัดการสารเคมีอันตรายครบถ้วน ตั้งแต่การจัดซื้อ จัดเก็บ การใช้งาน ไปจนถึงการกำจัด รวมถึงการจัดทำ SDS (Safety Data Sheet) และแบบรายงาน สอ.1-4 [ปรับปรุงตาม Design Thinking กลุ่ม 2]', 'ไม่มีระบบบริหารจัดการสารเคมีอันตราย', 'มีการดำเนินงานเบื้องต้น แต่ยังไม่ครบถ้วนตามกฎหมาย', 'มีระบบบริหารจัดการสารเคมีพื้นฐาน มี SDS ครบถ้วน ปฏิบัติตามกฎหมาย', 'มีระบบครบถ้วน มีแบบรายงาน สอ.1-4 ครบ มีการฝึกอบรมพนักงาน มีการติดตามและปรับปรุงสม่ำเสมอ', 'มีระบบที่เป็นเลิศ มีแผนฉุกเฉินสารเคมีและฝึกซ้อมอย่างน้อยปีละ 1 ครั้ง มีการจัดการตามมาตรฐานสากล มีผลลัพธ์ที่วัดได้', '', 0, 1, 1, 1.00, 6, 1, '2026-01-30 04:55:57', '2026-04-22 10:25:57'),
(22, 2, 'I2.7', 'การป้องกันและระงับอัคคีภัย', '(Fire Prevention &amp; Control)', 'สถานประกอบการมีระบบการป้องกันและระงับอัคคีภัยที่ครบถ้วน ตามพระราชบัญญัติความปลอดภัยฯ และมาตรฐานสากล', 'ไม่มีระบบการป้องกันอัคคีภัยหรือการดำเนินงาน', 'มีระบบการป้องกันอัคคีภัยเบื้องต้น แต่ยังไม่ครบถ้วนตามกฎหมาย', 'มีระบบและปฏิบัติตามกฎหมายขั้นพื้นฐาน มีหลักฐานการดำเนินงาน', 'มีระบบการป้องกันอัคคีภัยครบถ้วน มีการติดตามและปรับปรุงสม่ำเสมอ', 'มีระบบการป้องกันอัคคีภัยที่เป็นเลิศ เป็นไปตามมาตรฐานสากล มีการพัฒนาต่อเนื่อง มีผลลัพธ์ที่วัดได้', '', 0, 1, 1, 1.00, 7, 1, '2026-01-30 04:55:57', '2026-04-22 11:35:28'),
(23, 2, 'I2.8', 'แผนฉุกเฉิน การซ้อมรับมือเหตุฉุกเฉิน และการซ้อมหนีไฟ', '(Emergency Response Plan &amp; Evacuation Drill)', 'สถานประกอบการมีแผนฉุกเฉินที่ครอบคลุมเหตุการณ์ฉุกเฉินทุกประเภท (ไฟไหม้ สารเคมีรั่วไหล น้ำท่วม แผ่นดินไหว ฯลฯ) มีการฝึกซ้อมอย่างสม่ำเสมอ และมีการทบทวนปรับปรุงหลังการซ้อม [ปรับชื่อและเนื้อหาตาม Design Thinking กลุ่ม 2]', 'ไม่มีแผนฉุกเฉินและไม่มีการซ้อมหนีไฟ', 'มีแผนฉุกเฉินเบื้องต้น แต่ยังไม่ครอบคลุมและยังไม่มีการซ้อมตามกฎหมาย', 'มีแผนฉุกเฉินตามกฎหมาย มีการซ้อมหนีไฟอย่างน้อยปีละ 1 ครั้ง', 'มีแผนฉุกเฉินครอบคลุมหลายสถานการณ์ มีการซ้อมสม่ำเสมอ มีการทบทวนและปรับปรุงหลังซ้อม', 'มีแผนฉุกเฉินครบถ้วนทุกประเภทเหตุการณ์ มีการซ้อมหลายรูปแบบ มีการประเมินประสิทธิภาพ มีการพัฒนาต่อเนื่อง', '', 0, 1, 1, 1.00, 8, 1, '2026-01-30 04:55:57', '2026-04-22 11:37:37'),
(24, 2, 'I2.9', 'ความปลอดภัยเครื่องจักรและอุปกรณ์', '(Machine &amp; Equipment Safety)', 'สถานประกอบการมีระบบความปลอดภัยสำหรับเครื่องจักรและอุปกรณ์ ครอบคลุมการติดตั้ง การใช้งาน การบำรุงรักษา และการตรวจสอบตามกฎหมาย', 'ไม่มีระบบความปลอดภัยเครื่องจักรหรือการดำเนินงาน', 'มีระบบความปลอดภัยเครื่องจักรเบื้องต้น แต่ยังไม่ครบถ้วนตามกฎหมาย', 'มีระบบและปฏิบัติตามกฎหมายขั้นพื้นฐาน มีหลักฐานการดำเนินงาน', 'มีระบบความปลอดภัยเครื่องจักรครบถ้วน มีการติดตามและปรับปรุงสม่ำเสมอ', 'มีระบบความปลอดภัยเครื่องจักรที่เป็นเลิศ เป็นไปตามมาตรฐานสากล มีการพัฒนาต่อเนื่อง มีผลลัพธ์ที่วัดได้', '', 0, 1, 1, 1.00, 9, 1, '2026-01-30 04:55:57', '2026-04-22 11:39:04'),
(25, 2, 'I2.10', 'การจัดการคุณภาพอากาศและเสียง', '(Air Quality &amp; Noise Management)', 'สถานประกอบการมีการจัดการคุณภาพอากาศภายใน (Indoor Air Quality) และเสียงรบกวนในสถานที่ทำงาน ให้อยู่ในระดับที่ปลอดภัยตามกฎหมายและมาตรฐาน', 'ไม่มีระบบการจัดการคุณภาพอากาศและเสียงหรือการดำเนินงาน', 'มีระบบการจัดการคุณภาพอากาศและเสียงเบื้องต้น แต่ยังไม่ครบถ้วนตามกฎหมาย', 'มีระบบและปฏิบัติตามกฎหมายขั้นพื้นฐาน มีหลักฐานการดำเนินงาน', 'มีระบบการจัดการคุณภาพอากาศและเสียงครบถ้วน มีการติดตามและปรับปรุงสม่ำเสมอ', 'มีระบบการจัดการคุณภาพอากาศและเสียงที่เป็นเลิศ เป็นไปตามมาตรฐานสากล มีการพัฒนาต่อเนื่อง มีผลลัพธ์ที่วัดได้', '', 0, 1, 1, 1.00, 10, 1, '2026-01-30 04:55:57', '2026-04-22 11:40:25'),
(26, 2, 'I2.11', 'การจัดการน้ำเสียและของเสีย', '(Wastewater &amp; Waste Management)', 'สถานประกอบการมีระบบการจัดการน้ำเสียและของเสีย (รวมถึงของเสียอันตราย) ตามกฎหมายและมาตรฐานสิ่งแวดล้อม', 'ไม่มีระบบการจัดการน้ำเสียและของเสียหรือการดำเนินงาน', 'มีระบบการจัดการน้ำเสียและของเสียเบื้องต้น แต่ยังไม่ครบถ้วนตามกฎหมาย', 'มีระบบและปฏิบัติตามกฎหมายขั้นพื้นฐาน มีหลักฐานการดำเนินงาน', 'มีระบบการจัดการน้ำเสียและของเสียครบถ้วน มีการติดตามและปรับปรุงสม่ำเสมอ', 'มีระบบการจัดการน้ำเสียและของเสียที่เป็นเลิศ เป็นไปตามมาตรฐานสากล มีการพัฒนาต่อเนื่อง มีผลลัพธ์ที่วัดได้', '', 0, 1, 1, 1.00, 11, 1, '2026-01-30 04:55:57', '2026-04-22 11:41:36'),
(27, 2, 'I2.12', 'การประหยัดพลังงาน', '(Energy Conservation)', 'สถานประกอบการมีการดำเนินการด้านการประหยัดพลังงานและเพิ่มประสิทธิภาพการใช้พลังงาน ตามกฎหมายอนุรักษ์พลังงานและมาตรฐาน ISO 50001', 'ไม่มีระบบการประหยัดพลังงานหรือการดำเนินงาน', 'มีระบบการประหยัดพลังงานเบื้องต้น แต่ยังไม่ครบถ้วนตามกฎหมาย', 'มีระบบและปฏิบัติตามกฎหมายขั้นพื้นฐาน มีหลักฐานการดำเนินงาน', 'มีระบบการประหยัดพลังงานครบถ้วน มีการติดตามและปรับปรุงสม่ำเสมอ', 'มีระบบที่เป็นเลิศมีระบบการประหยัดพลังงานที่เป็นเลิศ เป็นไปตามมาตรฐานสากล มีการพัฒนาต่อเนื่อง มีผลลัพธ์ที่วัดได้ เป็นไปตามมาตรฐานสากล มีการพัฒนาต่อเนื่อง', '', 0, 1, 1, 1.00, 12, 1, '2026-01-30 04:55:57', '2026-04-22 11:43:00'),
(28, 2, 'I2.13', 'การจัดการก๊าซเรือนกระจก (GHG)', '(Greenhouse Gas Management)', 'สถานประกอบการมีการประเมิน รายงาน และจัดการการปล่อยก๊าซเรือนกระจก (GHG) ทั้ง Scope 1, 2 และ 3 ตามมาตรฐาน ISO 14064', 'ไม่มีการดำเนินงานด้าน GHG Management', 'มีความตระหนักด้าน GHG แต่ยังไม่มีระบบการวัดหรือรายงาน', 'มีการประเมิน GHG Scope 1 และ 2 มีรายงาน GHG ประจำปี', 'มีการประเมิน GHG ครบ Scope 1, 2, 3 มีแผนลดการปล่อย GHG มีการติดตามผลสม่ำเสมอ', 'มีระบบ GHG Management ที่เป็นเลิศ มี Science-Based Targets มีการรายงานตาม GRI หรือ CDP มีผลลัพธ์การลด GHG ที่วัดได้', '', 0, 1, 1, 1.00, 13, 1, '2026-01-30 04:55:57', '2026-04-22 11:44:20'),
(29, 2, 'I2.14', 'ระบบมาตรฐานสากล ISO ด้านความปลอดภัยและสิ่งแวดล้อม', '(ISO Certification (OHS &amp; Environment)', 'สถานประกอบการมีการดำเนินการตามระบบมาตรฐานสากล ISO ด้านความปลอดภัย (ISO 45001) และสิ่งแวดล้อม (ISO 14001) เพื่อยกระดับมาตรฐานการจัดการ', 'ไม่มีการดำเนินการตามมาตรฐาน ISO ด้านความปลอดภัยและสิ่งแวดล้อม', 'มีความสนใจและอยู่ระหว่างศึกษาการนำ ISO มาใช้', 'อยู่ระหว่างการนำระบบ ISO มาใช้ มีการจัดตั้งคณะทำงาน มีแผนงานชัดเจน', 'ได้รับการรับรอง ISO 45001 หรือ ISO 14001 อย่างน้อยหนึ่งระบบ มีการรักษาระบบอย่างต่อเนื่อง', 'ได้รับการรับรองทั้ง ISO 45001 และ ISO 14001 มีการบูรณาการระบบ (IMS) มีผลการ surveillance audit ที่ดี', '', 0, 1, 1, 1.00, 14, 1, '2026-01-30 04:55:57', '2026-04-22 11:45:33'),
(30, 2, 'I2.15', 'การตรวจ Audit ด้านความปลอดภัยและสิ่งแวดล้อม', '(Safety &amp; Environment Audit)', 'สถานประกอบการมีการตรวจประเมิน (Audit) ด้านความปลอดภัยและสิ่งแวดล้อมทั้งภายในและภายนอกอย่างสม่ำเสมอ และนำผลไปปรับปรุงอย่างต่อเนื่อง', 'ไม่มีระบบการตรวจ Auditหรือการดำเนินงาน', 'มีระบบการตรวจ Auditเบื้องต้น แต่ยังไม่ครบถ้วนตามกฎหมาย', 'มีระบบและปฏิบัติตามกฎหมายขั้นพื้นฐาน มีหลักฐานการดำเนินงาน', 'มีระบบการตรวจ Auditครบถ้วน มีการติดตามและปรับปรุงสม่ำเสมอ', 'มีระบบการตรวจ Auditที่เป็นเลิศ เป็นไปตามมาตรฐานสากล มีการพัฒนาต่อเนื่อง มีผลลัพธ์ที่วัดได้', '', 0, 1, 1, 1.00, 15, 1, '2026-01-30 04:55:57', '2026-04-22 11:46:47'),
(45, 3, 'C3.1+2', 'นโยบาย CSR และชุมชนสัมพันธ์เพื่อการมีส่วนร่วมของชุมชน', '(CSR &amp; Community Relations Policy)', 'สถานประกอบการมีนโยบาย CSR ที่ชัดเจนเป็นลายลักษณ์อักษร และมีการดำเนินงานด้านชุมชนสัมพันธ์เพื่อสร้างการมีส่วนร่วมของชุมชนอย่างยั่งยืน [รวม C3.1 + C3.2]', 'ไม่มีนโยบาย CSR และไม่มีการดำเนินงานด้านชุมชนสัมพันธ์', 'มีการดำเนินงาน CSR/ชุมชนสัมพันธ์เบื้องต้น เป็นครั้งคราว ยังไม่มีนโยบายเป็นลายลักษณ์อักษร', 'มีนโยบาย CSR เป็นลายลักษณ์อักษร มีโครงการและกิจกรรมชุมชนสัมพันธ์สม่ำเสมอ', 'มีนโยบาย CSR และโครงการชุมชนสัมพันธ์ที่ครอบคลุม มีการติดตามและประเมินผล มีการรายงานผู้บริหาร', 'มีนโยบาย CSR และโครงการชุมชนสัมพันธ์ที่ยั่งยืน สร้างคุณค่าร่วมกับชุมชน มีผลลัพธ์ที่วัดได้ มีการประเมินความพึงพอใจชุมชน 360 องศา', '', 0, 1, 1, 1.00, 1, 1, '2026-01-30 04:55:58', '2026-04-22 14:34:41'),
(46, 4, 'M4.1', 'ภาวะผู้นำและความมุ่งมั่นของผู้บริหาร', '(Leadership &amp; Commitment)', 'ผู้บริหารสูงสุดและทีมผู้บริหารแสดง visible leadership ด้านสุขภาวะและ ESG อย่างชัดเจน มีหลักฐานการมีส่วนร่วมในกิจกรรมสุขภาวะ และกำหนดเป็นวาระสำคัญขององค์กร [ปรับปรุงตาม Design Thinking กลุ่ม 4]', 'ไม่มีความมุ่งมั่นจากผู้บริหารด้านสุขภาวะและ ESG', 'ผู้บริหารรับรู้แต่ยังไม่มีการแสดงออกหรือการสนับสนุนอย่างเป็นรูปธรรม', 'ผู้บริหารให้การสนับสนุนและมีส่วนร่วมในกิจกรรมสุขภาวะ มีการสื่อสารทิศทางชัดเจน', 'ผู้บริหารแสดง visible leadership มีการกำหนด KPI ด้านสุขภาวะและ ESG ในระดับองค์กร มีการติดตามผลสม่ำเสมอ', 'ผู้บริหารเป็น role model ด้านสุขภาวะและ ESG มีหลักฐานการมีส่วนร่วมที่วัดได้ บูรณาการในยุทธศาสตร์องค์กร มีผลลัพธ์ที่เป็นรูปธรรม', '', 0, 1, 1, 1.00, 1, 1, '2026-01-30 04:55:58', '2026-04-22 14:46:46'),
(47, 4, 'M4.2', 'โครงสร้างองค์กรและบทบาทหน้าที่', '(Organizational Structure &amp; Roles)', 'สถานประกอบการมีโครงสร้างองค์กรและการกำหนดบทบาทหน้าที่ด้านสุขภาวะที่ชัดเจน ครอบคลุมทุกระดับ ตั้งแต่ระดับบริหารถึงระดับปฏิบัติการ', 'ไม่มีระบบโครงสร้างองค์กรและบทบาทหน้าที่หรือการดำเนินการ', 'มีระบบโครงสร้างองค์กรและบทบาทหน้าที่เบื้องต้น แต่ยังไม่เป็นทางการ', 'มีระบบโครงสร้างองค์กรและบทบาทหน้าที่ที่เป็นทางการ มีการดำเนินงานอย่างสม่ำเสมอ', 'มีระบบโครงสร้างองค์กรและบทบาทหน้าที่ที่มีประสิทธิภาพ มีการติดตามและปรับปรุง', 'มีระบบโครงสร้างองค์กรและบทบาทหน้าที่ที่เป็นเลิศ บูรณาการทั้งองค์กร มีผลลัพธ์ที่วัดได้ มีการพัฒนาต่อเนื่อง', '', 0, 1, 1, 1.00, 2, 1, '2026-01-30 04:55:58', '2026-04-22 14:47:50'),
(48, 4, 'M4.3', 'ระบบบูรณาการและเชื่อมโยงยุทธศาสตร์', '(Strategic Integration)', 'สถานประกอบการมีการบูรณาการเรื่องสุขภาวะ ความปลอดภัย ชุมชน และ ESG เข้ากับยุทธศาสตร์ระยะยาวขององค์กรอย่างชัดเจนและวัดผลได้', 'ไม่มีระบบระบบบูรณาการยุทธศาสตร์หรือการดำเนินการ', 'มีระบบระบบบูรณาการยุทธศาสตร์เบื้องต้น แต่ยังไม่เป็นทางการ', 'มีระบบระบบบูรณาการยุทธศาสตร์ที่เป็นทางการ มีการดำเนินงานอย่างสม่ำเสมอ', 'มีระบบระบบบูรณาการยุทธศาสตร์ที่มีประสิทธิภาพ มีการติดตามและปรับปรุง', 'มีระบบระบบบูรณาการยุทธศาสตร์ที่เป็นเลิศ บูรณาการทั้งองค์กร มีผลลัพธ์ที่วัดได้ มีการพัฒนาต่อเนื่อง', '', 0, 1, 1, 1.00, 3, 1, '2026-01-30 04:55:58', '2026-04-22 14:48:58'),
(49, 4, 'M4.4', 'ระบบ KPI และ Dashboard', '(KPI Dashboard System)', 'สถานประกอบการมีระบบ KPI และ Dashboard ที่แสดงตัวชี้วัดสุขภาวะ ความปลอดภัย ชุมชน และ ESG ในภาพเดียว สามารถติดตามผลแบบ real-time ได้ [ปรับปรุงตาม Design Thinking กลุ่ม 4]', 'ไม่มีระบบ KPI หรือ Dashboard', 'มีการกำหนด KPI เบื้องต้น แต่ยังไม่มีระบบการติดตาม', 'มีระบบ KPI ที่เป็นทางการ มีการรายงานผลสม่ำเสมอ', 'มีระบบ KPI Dashboard ที่ครอบคลุม มีการติดตาม real-time มีการวิเคราะห์แนวโน้ม', 'มีระบบ Integrated KPI Dashboard ที่แสดง HICM+ESG ในภาพเดียว มีการใช้ข้อมูลในการตัดสินใจ มีผลลัพธ์ที่วัดได้', '', 0, 1, 1, 1.00, 4, 1, '2026-01-30 04:55:58', '2026-04-22 14:50:06'),
(50, 4, 'M4.5', 'การประเมินผลและติดตาม (M&amp;E)', '(Monitoring &amp; Evaluation)', 'สถานประกอบการมีระบบการติดตามและประเมินผล (M&amp;E) ด้านสุขภาวะ ความปลอดภัย ชุมชน และ ESG ที่ครบถ้วนและต่อเนื่อง', 'ไม่มีระบบการประเมินผลและติดตาม M&amp;E หรือการดำเนินการ', 'มีระบบการประเมินผลและติดตาม M&amp;E เบื้องต้น แต่ยังไม่เป็นทางการ', 'มีระบบการประเมินผลและติดตาม M&amp;E ที่เป็นทางการ มีการดำเนินงานอย่างสม่ำเสมอ', 'มีระบบการประเมินผลและติดตาม M&amp;E ที่มีประสิทธิภาพ มีการติดตามและปรับปรุง', 'มีระบบการประเมินผลและติดตาม M&amp;E ที่เป็นเลิศ บูรณาการทั้งองค์กร มีผลลัพธ์ที่วัดได้ มีการพัฒนาต่อเนื่อง', '', 0, 1, 1, 1.00, 5, 1, '2026-01-30 04:55:58', '2026-04-22 14:51:15'),
(51, 4, 'M4.6', 'การบริหารความเสี่ยงองค์กร (ERM)', '(Enterprise Risk Management)', 'สถานประกอบการมีระบบการบริหารความเสี่ยงองค์กร (ERM) ที่บูรณาการ health &amp; safety risks เข้ากับ enterprise risk management framework [ปรับปรุงตาม Design Thinking กลุ่ม 4]', 'ไม่มีระบบ ERM', 'มีการระบุความเสี่ยงเบื้องต้น แต่ยังไม่เป็นระบบ ERM', 'มีระบบ ERM เบื้องต้น มีการระบุและประเมินความเสี่ยงหลัก', 'มีระบบ ERM ที่ครบถ้วน บูรณาการ health &amp; safety risks มีการติดตามและปรับปรุงสม่ำเสมอ', 'มีระบบ ERM ที่เป็นเลิศ บูรณาการ ESG risks ครบถ้วน รายงานต่อ Board มีการ stress testing มีผลลัพธ์วัดได้', '', 0, 1, 1, 1.00, 6, 1, '2026-01-30 04:55:58', '2026-04-22 14:56:47'),
(52, 4, 'M4.7', 'การปฏิบัติตามจริยธรรมและธรรมาภิบาล', '(Compliance, Ethics &amp; Governance)', 'สถานประกอบการมีระบบการปฏิบัติตามกฎหมาย จริยธรรมองค์กร และหลักธรรมาภิบาล (Governance) ที่ครบถ้วนและโปร่งใส', 'ไม่มีระบบการปฏิบัติตามจริยธรรมและธรรมาภิบาลหรือการดำเนินการ', 'มีระบบการปฏิบัติตามจริยธรรมและธรรมาภิบาลเบื้องต้น แต่ยังไม่เป็นทางการ', 'มีระบบการปฏิบัติตามจริยธรรมและธรรมาภิบาลที่เป็นทางการ มีการดำเนินงานอย่างสม่ำเสมอ', 'มีระบบการปฏิบัติตามจริยธรรมและธรรมาภิบาลที่มีประสิทธิภาพ มีการติดตามและปรับปรุง', 'มีระบบการปฏิบัติตามจริยธรรมและธรรมาภิบาลที่เป็นเลิศ บูรณาการทั้งองค์กร มีผลลัพธ์ที่วัดได้ มีการพัฒนาต่อเนื่อง', '', 0, 1, 1, 1.00, 7, 1, '2026-01-30 04:55:58', '2026-04-22 14:57:55'),
(53, 4, 'M4.8', 'การพัฒนาศักยภาพบุคลากร', '(Capacity Building &amp; Learning)', 'สถานประกอบการมีระบบการพัฒนาศักยภาพบุคลากรด้านสุขภาวะ ความปลอดภัย และ ESG อย่างต่อเนื่องและครบถ้วน', 'ไม่มีระบบการพัฒนาศักยภาพบุคลากรหรือการดำเนินการ', 'มีระบบการพัฒนาศักยภาพบุคลากรเบื้องต้น แต่ยังไม่เป็นทางการ', 'มีระบบการพัฒนาศักยภาพบุคลากรที่เป็นทางการ มีการดำเนินงานอย่างสม่ำเสมอ', 'มีระบบการพัฒนาศักยภาพบุคลากรที่มีประสิทธิภาพ มีการติดตามและปรับปรุง', 'มีระบบการพัฒนาศักยภาพบุคลากรที่เป็นเลิศ บูรณาการทั้งองค์กร มีผลลัพธ์ที่วัดได้ มีการพัฒนาต่อเนื่อง', '', 0, 1, 1, 1.00, 8, 1, '2026-01-30 04:55:58', '2026-04-22 14:58:56'),
(54, 4, 'M4.9', 'การคุ้มครองข้อมูลสุขภาพ (PDPA)', '(Health Data Privacy (PDPA)', 'สถานประกอบการมีระบบ data governance ที่ครอบคลุมข้อมูลสุขภาพพนักงานและข้อมูลชุมชน ปฏิบัติตาม พ.ร.บ. PDPA อย่างครบถ้วน [ปรับปรุงตาม Design Thinking กลุ่ม 4]', 'ไม่มีระบบคุ้มครองข้อมูลส่วนบุคคล', 'มีความตระหนักด้าน PDPA แต่ยังไม่มีระบบที่เป็นทางการ', 'มีนโยบาย PDPA ที่เป็นทางการ มีการฝึกอบรมพนักงาน มีระบบการจัดการข้อมูล', 'มีระบบ PDPA ครบถ้วน มีการทำ DPIA สำหรับข้อมูลสุขภาพ มีการตรวจสอบประจำปี', 'มีระบบ Data Governance ที่เป็นเลิศ ครอบคลุมข้อมูลสุขภาพและชุมชน มีการ audit และรายงานต่อผู้บริหาร มีผลลัพธ์ที่วัดได้', '', 0, 1, 1, 1.00, 9, 1, '2026-01-30 04:55:58', '2026-04-22 15:00:24'),
(55, 4, 'M4.10', 'นวัตกรรมสุขภาพและความปลอดภัย', '(Health &amp; Safety Innovation)', 'สถานประกอบการมีโปรแกรม innovation ด้านสุขภาวะที่วัดผล ROI ได้ และเชื่อมกับ digital transformation ขององค์กร [ปรับปรุงตาม Design Thinking กลุ่ม 4]', 'ไม่มีการนำนวัตกรรมมาใช้ด้านสุขภาวะและความปลอดภัย', 'มีความสนใจในนวัตกรรม แต่ยังไม่มีการนำมาใช้จริง', 'มีการนำนวัตกรรมบางส่วนมาใช้ มีผลลัพธ์เบื้องต้น', 'มีโปรแกรมนวัตกรรมที่ชัดเจน มีการวัด ROI มีการบูรณาการกับ digital transformation', 'มีระบบนวัตกรรมสุขภาวะที่เป็นเลิศ มีผล ROI ที่วัดได้ สร้าง competitive advantage มีการพัฒนาต่อเนื่อง', '', 0, 1, 1, 1.00, 10, 1, '2026-01-30 04:55:58', '2026-04-22 15:02:15'),
(56, 4, 'M4.11', 'ระบบรางวัลและแรงจูงใจ', '(Reward &amp; Incentive System)', 'สถานประกอบการมีระบบรางวัลและแรงจูงใจที่เชื่อมโยงกับผลการดำเนินงานด้านสุขภาวะ ความปลอดภัย และ ESG เพื่อกระตุ้นการมีส่วนร่วมของพนักงาน', 'ไม่มีระบบระบบรางวัลและแรงจูงใจหรือการดำเนินการ', 'มีระบบระบบรางวัลและแรงจูงใจเบื้องต้น แต่ยังไม่เป็นทางการ', 'มีระบบระบบรางวัลและแรงจูงใจที่เป็นทางการ มีการดำเนินงานอย่างสม่ำเสมอ', 'มีระบบระบบรางวัลและแรงจูงใจที่มีประสิทธิภาพ มีการติดตามและปรับปรุง', 'มีระบบระบบรางวัลและแรงจูงใจที่เป็นเลิศ บูรณาการทั้งองค์กร มีผลลัพธ์ที่วัดได้ มีการพัฒนาต่อเนื่อง', '', 0, 1, 1, 1.00, 11, 1, '2026-01-30 04:55:58', '2026-04-22 15:03:31'),
(57, 4, 'M4.12', 'งบประมาณและการจัดสรรทรัพยากร', '(Budget &amp; Resource Allocation)', 'สถานประกอบการมีการจัดสรรงบประมาณและทรัพยากรด้านสุขภาวะ ความปลอดภัย ชุมชน และ ESG อย่างเพียงพอและมีประสิทธิภาพ', 'ไม่มีระบบงบประมาณและการจัดสรรทรัพยากรหรือการดำเนินการ', 'มีระบบงบประมาณและการจัดสรรทรัพยากรเบื้องต้น แต่ยังไม่เป็นทางการ', 'มีระบบงบประมาณและการจัดสรรทรัพยากรที่เป็นทางการ มีการดำเนินงานอย่างสม่ำเสมอ', 'มีระบบงบประมาณและการจัดสรรทรัพยากรที่มีประสิทธิภาพ มีการติดตามและปรับปรุง', 'มีระบบงบประมาณและการจัดสรรทรัพยากรที่เป็นเลิศ บูรณาการทั้งองค์กร มีผลลัพธ์ที่วัดได้ มีการพัฒนาต่อเนื่อง', '', 0, 1, 1, 1.00, 12, 1, '2026-01-30 04:55:58', '2026-04-22 15:04:30'),
(58, 4, 'M4.13', 'การสื่อสารและการมีส่วนร่วมของพนักงาน', '(Communication &amp; Employee Engagement)', 'สถานประกอบการมีระบบการสื่อสารและการมีส่วนร่วมของพนักงานด้านสุขภาวะและ ESG ที่มีประสิทธิภาพและครอบคลุมทุกระดับ', 'ไม่มีระบบการสื่อสารและการมีส่วนร่วมของพนักงานหรือการดำเนินการ', 'มีระบบการสื่อสารและการมีส่วนร่วมของพนักงานเบื้องต้น แต่ยังไม่เป็นทางการ', 'มีระบบการสื่อสารและการมีส่วนร่วมของพนักงานที่เป็นทางการ มีการดำเนินงานอย่างสม่ำเสมอ', 'มีระบบการสื่อสารและการมีส่วนร่วมของพนักงานที่มีประสิทธิภาพ มีการติดตามและปรับปรุง', 'มีระบบการสื่อสารและการมีส่วนร่วมของพนักงานที่เป็นเลิศ บูรณาการทั้งองค์กร มีผลลัพธ์ที่วัดได้ มีการพัฒนาต่อเนื่อง', '', 0, 1, 1, 1.00, 13, 1, '2026-01-30 04:55:58', '2026-04-22 15:07:49'),
(59, 4, 'M4.14', 'ระบบจัดการเอกสารและความรู้', '(Document &amp; Knowledge Management)', 'สถานประกอบการมีระบบจัดการเอกสารและการจัดการความรู้ด้านสุขภาวะ ความปลอดภัย และ ESG ที่มีประสิทธิภาพ เข้าถึงได้ง่าย และเป็นปัจจุบัน', 'ไม่มีระบบระบบจัดการเอกสารและความรู้หรือการดำเนินการ', 'มีระบบระบบจัดการเอกสารและความรู้เบื้องต้น แต่ยังไม่เป็นทางการ', 'มีระบบระบบจัดการเอกสารและความรู้ที่เป็นทางการ มีการดำเนินงานอย่างสม่ำเสมอ', 'มีระบบระบบจัดการเอกสารและความรู้ที่มีประสิทธิภาพ มีการติดตามและปรับปรุง', 'มีระบบระบบจัดการเอกสารและความรู้ที่เป็นเลิศ บูรณาการทั้งองค์กร มีผลลัพธ์ที่วัดได้ มีการพัฒนาต่อเนื่อง', '', 0, 1, 1, 1.00, 14, 1, '2026-01-30 04:55:58', '2026-04-22 15:09:18'),
(60, 4, 'M4.15', 'การปรับปรุงอย่างต่อเนื่อง (CI)', '(Continuous Improvement)', 'สถานประกอบการมีระบบการปรับปรุงอย่างต่อเนื่อง (CI) ที่ใช้ evidence-based approach และเชื่อมกับ learning organization [ปรับปรุงตาม Design Thinking กลุ่ม 4]', 'ไม่มีระบบการปรับปรุงอย่างต่อเนื่อง', 'มีการปรับปรุงเป็นครั้งคราว แต่ยังไม่มีระบบที่ชัดเจน', 'มีระบบ CI ที่เป็นทางการ มีการดำเนินการตาม PDCA Cycle', 'มีระบบ CI ที่มีประสิทธิภาพ มีการใช้ข้อมูลและ evidence ในการปรับปรุง มีการติดตามผล', 'มีระบบ CI ที่เป็นเลิศ ใช้ evidence-based approach บูรณาการกับ learning organization มีผลลัพธ์ที่วัดได้และพัฒนาต่อเนื่อง', '', 0, 1, 1, 1.00, 15, 1, '2026-01-30 04:55:58', '2026-04-22 15:10:31'),
(62, 2, 'I2.16', 'ความปลอดภัยด้านไฟฟ้า', '(Electrical Safety)', 'สถานประกอบการมีระบบความปลอดภัยด้านไฟฟ้าที่ครบถ้วน ครอบคลุมการติดตั้ง การตรวจสอบ การบำรุงรักษา และการป้องกันอันตรายจากไฟฟ้า ตามกฎหมายและมาตรฐาน [ตัวชี้วัดเฉพาะทางใหม่ ตาม Design Thinking กลุ่ม 2]', 'ไม่มีระบบความปลอดภัยด้านไฟฟ้าหรือการดำเนินงาน', 'มีระบบความปลอดภัยด้านไฟฟ้าเบื้องต้น แต่ยังไม่ครบถ้วนตามกฎหมาย', 'มีระบบและปฏิบัติตามกฎหมายขั้นพื้นฐาน มีหลักฐานการดำเนินงาน', 'มีระบบความปลอดภัยด้านไฟฟ้าครบถ้วน มีการติดตามและปรับปรุงสม่ำเสมอ', 'มีระบบความปลอดภัยด้านไฟฟ้าที่เป็นเลิศ เป็นไปตามมาตรฐานสากล มีการพัฒนาต่อเนื่อง มีผลลัพธ์ที่วัดได้', '', 0, 1, 1, 1.00, 16, 1, '2026-04-22 11:48:44', '2026-04-22 11:48:44'),
(63, 2, 'I2.17', 'ความปลอดภัยในที่อับอากาศ', '(Confined Space Safety)', 'สถานประกอบการมีระบบการบริหารจัดการความปลอดภัยในที่อับอากาศ ครอบคลุมการระบุพื้นที่ การขออนุญาต การตรวจวัดบรรยากาศ และการช่วยเหลือฉุกเฉิน [ตัวชี้วัดเฉพาะทางใหม่]', 'ไม่มีระบบความปลอดภัยในที่อับอากาศหรือการดำเนินงาน', 'มีระบบความปลอดภัยในที่อับอากาศเบื้องต้น แต่ยังไม่ครบถ้วนตามกฎหมาย', 'มีระบบและปฏิบัติตามกฎหมายขั้นพื้นฐาน มีหลักฐานการดำเนินงาน', 'มีระบบความปลอดภัยในที่อับอากาศครบถ้วน มีการติดตามและปรับปรุงสม่ำเสมอ', 'มีระบบความปลอดภัยในที่อับอากาศที่เป็นเลิศ เป็นไปตามมาตรฐานสากล มีการพัฒนาต่อเนื่อง มีผลลัพธ์ที่วัดได้', '', 0, 1, 1, 1.00, 17, 1, '2026-04-22 11:50:16', '2026-04-22 11:50:16'),
(64, 2, 'I2.18', 'ความปลอดภัยงานประดาน้ำและใต้น้ำ', '(Diving &amp; Underwater Work Safety)', 'สถานประกอบการที่มีงานประดาน้ำหรือใต้น้ำมีระบบความปลอดภัยที่ครบถ้วน ครอบคลุมการรับรองบุคลากร อุปกรณ์ และขั้นตอนการทำงาน [ตัวชี้วัดเฉพาะทางใหม่]', 'ไม่มีระบบความปลอดภัยงานประดาน้ำ', 'มีระบบเบื้องต้น แต่ยังไม่ครบถ้วนตามมาตรฐาน', 'มีระบบและปฏิบัติตามกฎหมายขั้นพื้นฐาน มีใบรับรองนักประดาน้ำ', 'มีระบบครบถ้วน มีการตรวจสอบอุปกรณ์สม่ำเสมอ มีแผนฉุกเฉินใต้น้ำ', 'มีระบบที่เป็นเลิศตามมาตรฐานสากล (IMCA/HSE) มีการฝึกซ้อมฉุกเฉินใต้น้ำ มีผลลัพธ์วัดได้', 'ไม่มีงานประดาน้ำ', 1, 1, 1, 1.00, 18, 1, '2026-04-22 11:54:52', '2026-04-22 11:54:52'),
(65, 2, 'I2.19', 'ความปลอดภัยงานก่อสร้างและทำงานบนที่สูง', '(Construction &amp; Working at Height Safety)', 'สถานประกอบการมีระบบความปลอดภัยสำหรับงานก่อสร้างและงานบนที่สูง ครอบคลุมการประเมินความเสี่ยง ระบบป้องกันตก อุปกรณ์ PPE และการอบรมบุคลากร [ตัวชี้วัดเฉพาะทางใหม่]', 'ไม่มีระบบความปลอดภัยงานก่อสร้างและทำงานบนที่สูงหรือการดำเนินงาน', 'มีระบบความปลอดภัยงานก่อสร้างและทำงานบนที่สูงเบื้องต้น แต่ยังไม่ครบถ้วนตามกฎหมาย', 'มีระบบและปฏิบัติตามกฎหมายขั้นพื้นฐาน มีหลักฐานการดำเนินงาน', 'มีระบบความปลอดภัยงานก่อสร้างและทำงานบนที่สูงครบถ้วน มีการติดตามและปรับปรุงสม่ำเสมอ', 'มีระบบความปลอดภัยงานก่อสร้างและทำงานบนที่สูงที่เป็นเลิศ เป็นไปตามมาตรฐานสากล มีการพัฒนาต่อเนื่อง มีผลลัพธ์ที่วัดได้', '', 0, 1, 1, 1.00, 19, 1, '2026-04-22 11:56:47', '2026-04-22 11:57:17'),
(66, 2, 'I2.20', 'ความปลอดภัยด้านรังสี', '(Radiation Safety)', 'สถานประกอบการที่มีการใช้รังสีมีระบบความปลอดภัยด้านรังสีที่ครบถ้วน ครอบคลุมการใบอนุญาต การวัดปริมาณรังสี การป้องกัน และการจัดการกากกัมมันตภาพรังสี [ตัวชี้วัดเฉพาะทางใหม่]', 'ไม่มีระบบความปลอดภัยด้านรังสี', 'มีระบบเบื้องต้น แต่ยังไม่ครบถ้วนตามกฎหมาย', 'มีใบอนุญาตครบถ้วน มีการวัดปริมาณรังสีพนักงาน มีการจัดเก็บตามกฎหมาย', 'มีระบบครบถ้วน มีเจ้าหน้าที่ความปลอดภัยด้านรังสี มีการทบทวนประจำปี', 'มีระบบที่เป็นเลิศตามมาตรฐาน IAEA มีการบริหารปริมาณรังสีรวม (Collective Dose) มีผลลัพธ์วัดได้', 'ไม่มีการใช้รังสี', 1, 1, 1, 1.00, 20, 1, '2026-04-22 11:58:58', '2026-04-22 11:58:58'),
(67, 2, 'I2.21', 'ความปลอดภัยการยกและเคลื่อนย้ายด้วยแรงงานคน', '(Manual Handling &amp; Ergonomics Safety)', 'สถานประกอบการมีระบบการประเมินและควบคุมความเสี่ยงจากการยกและเคลื่อนย้ายสิ่งของด้วยแรงงานคน (Manual Handling) และด้าน Ergonomics เพื่อป้องกันการบาดเจ็บกล้ามเนื้อและกระดูก (MSDs) [ตัวชี้วัดเฉพาะทางใหม่]', 'ไม่มีการประเมินหรือควบคุมความเสี่ยง Manual Handling', 'มีการดำเนินงานเบื้องต้น เช่น ป้ายแนะนำ แต่ยังไม่เป็นระบบ', 'มีการประเมินความเสี่ยง Manual Handling มีการฝึกอบรมเทคนิคการยกที่ถูกต้อง', 'มีการปรับปรุง Ergonomics ในสถานที่ทำงาน มีระบบติดตาม MSDs มีการประเมินผล', 'มีระบบ Ergonomics Management ที่เป็นเลิศ มีผลลัพธ์วัดได้ (% ลด MSDs) มีการนำ Technology มาช่วยลด Manual Handling', '', 0, 1, 1, 1.00, 21, 1, '2026-04-22 12:00:07', '2026-04-22 12:00:07'),
(68, 3, 'C3.3+14', 'ช่องทางรับฟังความคิดเห็นและการประเมินความพึงพอใจของชุมชน', '(Community Feedback &amp; Satisfaction Assessment)', 'สถานประกอบการมีช่องทางรับฟังความคิดเห็นและข้อร้องเรียนจากชุมชน พร้อมทั้งมีการประเมินความพึงพอใจของชุมชนอย่างต่อเนื่อง [รวม C3.3 + C3.14]', 'ไม่มีช่องทางรับฟังความคิดเห็นและไม่มีการประเมินความพึงพอใจชุมชน', 'มีช่องทางรับฟังเบื้องต้น ใช้เป็นครั้งคราว ยังไม่ต่อเนื่อง', 'มีการจัดทำโครงการรับฟังความคิดเห็นและประเมินความพึงพอใจอย่างสม่ำเสมอ', 'มีโครงการที่ครอบคลุม มีระบบติดตามและประเมินผลการดำเนินงานอย่างเป็นระบบ', 'มีโครงการที่ยั่งยืน สร้างคุณค่าร่วมกับชุมชน มีผลลัพธ์ที่วัดได้ มีการนำผลมาปรับปรุงอย่างต่อเนื่อง', '', 0, 1, 1, 1.00, 2, 1, '2026-04-22 14:35:55', '2026-04-22 14:35:55'),
(69, 3, 'C3.4+5', 'โครงการส่งเสริมสุขภาพและพัฒนาคุณภาพชีวิตชุมชน', '(Community Health &amp; Quality of Life Promotion)', 'สถานประกอบการมีการดำเนินงานโครงการส่งเสริมสุขภาพและพัฒนาคุณภาพชีวิตของชุมชนอย่างต่อเนื่อง [รวม C3.4 + C3.5]', 'ไม่มีโครงการส่งเสริมสุขภาพหรือพัฒนาคุณภาพชีวิตชุมชน', 'มีการดำเนินงานเบื้องต้น เป็นครั้งคราว ยังไม่มีโครงการที่ชัดเจน', 'มีโครงการและกิจกรรมส่งเสริมสุขภาพ/พัฒนาคุณภาพชีวิตชุมชนสม่ำเสมอ', 'มีโครงการที่ครอบคลุม มีการติดตามและประเมินผลกระทบต่อสุขภาพและคุณภาพชีวิตชุมชน', 'มีโครงการที่ยั่งยืน สร้างคุณค่าร่วมกับชุมชน มีผลลัพธ์ที่วัดได้ด้านสุขภาพและคุณภาพชีวิต พัฒนาอย่างต่อเนื่อง', '', 0, 1, 1, 1.00, 3, 1, '2026-04-22 14:36:58', '2026-04-22 14:36:58'),
(70, 3, 'C3.6', 'การสนับสนุนการศึกษาและทุนการศึกษา', '(Education Support)', 'สถานประกอบการมีการดำเนินงานด้านการสนับสนุนการศึกษาและทุนการศึกษาให้แก่เยาวชนและชุมชน อย่างต่อเนื่องและสร้างผลกระทบเชิงบวก', 'ไม่มีการสนับสนุนการศึกษาหรือทุนการศึกษา', 'มีการสนับสนุนการศึกษาเบื้องต้น เป็นครั้งคราว ยังไม่ต่อเนื่อง', 'มีโครงการสนับสนุนการศึกษาและทุนการศึกษาที่สม่ำเสมอ', 'มีโครงการที่ครอบคลุม มีการติดตามผลผู้รับทุน มีการประเมินผลโครงการ', 'มีโครงการที่ยั่งยืน สร้างคุณค่าร่วมกับชุมชน มีผลลัพธ์ที่วัดได้ชัดเจน', '', 0, 1, 1, 1.00, 4, 1, '2026-04-22 14:38:23', '2026-04-22 14:38:23'),
(71, 3, 'C3.7', 'การส่งเสริมอาชีพและรายได้ชุมชน', '(Occupation &amp; Income Generation)', 'สถานประกอบการมีการดำเนินงานด้านการส่งเสริมอาชีพและรายได้ให้แก่ชุมชน เพื่อสร้างความเข้มแข็งทางเศรษฐกิจให้ชุมชนอย่างต่อเนื่องและยั่งยืน', 'ไม่มีการส่งเสริมอาชีพหรือรายได้ชุมชน', 'มีการดำเนินงานเบื้องต้น เป็นครั้งคราว ยังไม่ต่อเนื่อง', 'มีโครงการส่งเสริมอาชีพชุมชนที่สม่ำเสมอ มีหลักฐานประกอบ', 'มีโครงการที่ครอบคลุม มีการติดตามรายได้ที่เพิ่มขึ้น มีการประเมินผล', 'มีโครงการที่ยั่งยืน สร้างคุณค่าร่วมกับชุมชน มีผลลัพธ์ด้านรายได้ชุมชนที่วัดได้', '', 0, 1, 1, 1.00, 5, 1, '2026-04-22 14:39:47', '2026-04-22 14:39:47'),
(72, 3, 'C3.8+9', 'การดูแลสิ่งแวดล้อมและการจัดการผลกระทบต่อชุมชน', '(Community Environment &amp; Impact Management)', 'สถานประกอบการมีการดำเนินงานด้านการดูแลสิ่งแวดล้อมชุมชนโดยรอบและการจัดการผลกระทบจากการดำเนินงานขององค์กรต่อชุมชน [รวม C3.8 + C3.9]', 'ไม่มีการดูแลสิ่งแวดล้อมชุมชนและไม่มีการจัดการผลกระทบต่อชุมชน', 'มีการดำเนินงานเบื้องต้น เป็นครั้งคราว', 'มีโครงการดูแลสิ่งแวดล้อมและจัดการผลกระทบที่สม่ำเสมอ มีหลักฐานประกอบ', 'มีโครงการที่ครอบคลุม มีระบบติดตามผลกระทบและประเมินผล มีการแก้ไขปัญหาอย่างทันท่วงที', 'มีโครงการที่ยั่งยืน สร้างผลกระทบเชิงบวกต่อสิ่งแวดล้อมชุมชน มีผลลัพธ์ที่วัดได้', '', 0, 1, 1, 1.00, 6, 1, '2026-04-22 14:40:48', '2026-04-22 14:40:48'),
(73, 3, 'C3.10', 'การสนับสนุนระบบนิเวศการมีส่วนร่วมกับชุมชน', '(Community Ecosystem Support for Engagement)', 'สถานประกอบการมีการสนับสนุนโครงสร้างพื้นฐานและระบบนิเวศที่เอื้อต่อการมีส่วนร่วมของชุมชน ทั้งในระดับรอบโรงงาน ระดับชุมชน และระดับครอบครัว', 'ไม่มีการสนับสนุนระบบนิเวศหรือโครงสร้างพื้นฐานชุมชน', 'มีการสนับสนุนเบื้องต้น เป็นครั้งคราว', 'มีโครงการสนับสนุนระบบนิเวศชุมชนที่สม่ำเสมอ มีหลักฐาน', 'มีโครงการที่ครอบคลุม มีการวางระบบนิเวศการมีส่วนร่วม (รอบโรงงาน ชุมชน ครอบครัว) มีการประเมินผล', 'มีโครงการที่ยั่งยืน สร้างคุณค่าร่วมกับชุมชน มีระบบนิเวศที่เข้มแข็ง มีผลลัพธ์ที่วัดได้', '', 0, 1, 1, 1.00, 7, 1, '2026-04-22 14:41:53', '2026-04-22 14:41:53'),
(74, 3, 'C3.11', 'การส่งเสริมวัฒนธรรมและประเพณีท้องถิ่น', '(Local Culture &amp; Tradition Promotion)', 'สถานประกอบการมีการดำเนินงานด้านการส่งเสริมและสืบสานวัฒนธรรม ประเพณี และอัตลักษณ์ท้องถิ่น เพื่อสร้างความผูกพันและความภาคภูมิใจให้แก่ชุมชน', 'ไม่มีการส่งเสริมวัฒนธรรมและประเพณีท้องถิ่น', 'มีการดำเนินงานเบื้องต้น เป็นครั้งคราว', 'มีโครงการส่งเสริมวัฒนธรรมท้องถิ่นที่สม่ำเสมอ มีหลักฐาน', 'มีโครงการที่ครอบคลุม มีการติดตามผลและประเมินผลกระทบต่อการสืบสานวัฒนธรรม', 'มีโครงการที่ยั่งยืน สร้างคุณค่าร่วมกับชุมชน มีผลลัพธ์ด้านการสืบสานวัฒนธรรมที่วัดได้', '', 0, 1, 1, 1.00, 8, 1, '2026-04-22 14:42:59', '2026-04-22 14:42:59'),
(75, 3, 'C3.12+13', 'การประสานงานท้องถิ่นและการสื่อสารรายงาน CSR', '(Local Coordination &amp; CSR Communication)', 'สถานประกอบการมีการประสานงานกับหน่วยงานท้องถิ่น (อปท. อำเภอ จังหวัด) อย่างต่อเนื่อง มีการจัดทำและเผยแพร่รายงาน CSR อย่างโปร่งใส [รวม C3.12 + C3.13]', 'ไม่มีการประสานงานท้องถิ่นและไม่มีการรายงาน CSR', 'มีการประสานงานท้องถิ่นเบื้องต้น เป็นครั้งคราว ยังไม่มีรายงาน CSR อย่างเป็นทางการ', 'มีการประสานงานท้องถิ่นสม่ำเสมอ มีการจัดทำรายงาน CSR หรือสื่อสารผลการดำเนินงาน', 'มีการประสานงานท้องถิ่นอย่างเป็นระบบ มีรายงาน CSR ที่ครอบคลุม มีการเผยแพร่สู่สาธารณะ', 'มีการประสานงานท้องถิ่นที่เข้มแข็ง มีรายงาน CSR โปร่งใสตาม GRI Standards มีผลลัพธ์ที่วัดได้', '', 0, 1, 1, 1.00, 9, 1, '2026-04-22 14:44:02', '2026-04-22 14:44:02'),
(76, 3, 'C3.15', 'โครงการอาสาสมัครพนักงานเพื่อชุมชน', '(Employee Volunteer Program)', 'สถานประกอบการมีโครงการส่งเสริมและสนับสนุนให้พนักงานมีจิตอาสาและเข้าร่วมกิจกรรมอาสาสมัครเพื่อชุมชน มีระบบบันทึกชั่วโมงจิตอาสา และมีการยกย่องเชิดชูพนักงานจิตอาสา', 'ไม่มีโครงการอาสาสมัครพนักงาน', 'มีกิจกรรมอาสาสมัครเบื้องต้น เป็นครั้งคราว ยังไม่เป็นโครงการที่ชัดเจน', 'มีโครงการอาสาสมัครที่สม่ำเสมอ มีการบันทึกกิจกรรม มีหลักฐาน', 'มีโครงการที่ครอบคลุม มีระบบบันทึกชั่วโมงจิตอาสา มีการยกย่องพนักงานจิตอาสา มีการประเมินผล', 'มีโครงการที่ยั่งยืน มีพนักงานเข้าร่วมในระดับสูง มีผลลัพธ์ต่อชุมชนที่วัดได้ สร้างวัฒนธรรมจิตอาสาในองค์กร', '', 0, 1, 1, 1.00, 10, 1, '2026-04-22 14:45:09', '2026-04-22 14:45:09');
INSERT INTO `industry_categories` (`id`, `name_th`, `name_en`, `description`, `icon`, `color`, `display_order`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'อาหารและเกษตร', 'Food and Beverage Processing, Agricultural Product, Frozen Food', 'อุตสาหกรรมอาหาร เครื่องดื่ม และเกษตรกรรม', 'seedling', '#10b981', 1, 1, '2026-02-04 00:54:46', '2026-02-04 01:00:05'),
