INSERT INTO `organizations` (`id`, `name`, `short_name`, `description`, `contact_phone`, `contact_email`, `address`, `website`, `logo`, `display_order`, `is_active`, `created_at`, `updated_at`, `created_by`) VALUES
(1, 'สำนักสนับสนุนสุขภาวะองค์กร (สำนัก 8)', 'สำนัก 8', 'หน่วยงานภายใต้ สสส. ดูแลด้านสุขภาวะองค์กรและสถานประกอบการ ส่งเสริมให้องค์กรมีสภาพแวดล้อมที่เอื้อต่อการมีสุขภาพดี', '02-343-1500', 'office8@thaihealth.or.th', '99/8 อาคารศูนย์เรียนรู้สุขภาวะ ถ.สาทรใต้ แขวงยานนาวา เขตสาทร กรุงเทพฯ 10120', 'https://www.thaihealth.or.th', NULL, 1, 1, '2026-02-03 15:45:29', '2026-02-03 15:59:11', NULL),
(2, 'สำนักงานแรงงานจังหวัดนครราชสีมา-กระทรวงแรงงาน', 'แรงงานจังหวัด', 'หน่วยงานราชการส่วนภูมิภาคสังกัดกระทรวงแรงงาน ดูแลด้านแรงงานและการจ้างงานในจังหวัดนครราชสีมา', '044-243-098', 'nakhonratchasima@mol.go.th', 'ศาลากลางจังหวัดนครราชสีมา ชั้น 3 ถ.มหาดไทย ต.ในเมือง อ.เมือง จ.นครราชสีมา 30000', 'https://nakhonratchasima.mol.go.th', NULL, 2, 1, '2026-02-03 15:45:29', '2026-02-03 15:59:11', NULL),
(3, 'สำนักงานสาธารณสุขจังหวัดนครราชสีมา', 'สสจ.นครราชสีมา', 'หน่วยงานราชการดูแลด้านสาธารณสุข การส่งเสริมสุขภาพ และป้องกันโรคในพื้นที่จังหวัดนครราชสีมา', '044-465-010', 'saraban_nmss@health.moph.go.th', '255 ถ.มิตรภาพ ต.ในเมือง อ.เมือง จ.นครราชสีมา 30000', 'https://korathealth.com', NULL, 3, 1, '2026-02-03 15:45:29', '2026-02-03 15:59:11', NULL),
(4, 'องค์การบริหารส่วนจังหวัดนครราชสีมา', 'อบจ.นครราชสีมา', 'องค์กรปกครองส่วนท้องถิ่นระดับจังหวัด ดูแลด้านการพัฒนาท้องถิ่นและบริการสาธารณะ', '044-251-111', 'saraban@koratpao.go.th', '1111 ถ.มิตรภาพ ต.ในเมือง อ.เมือง จ.นครราชสีมา 30000', 'https://www.koratpao.go.th', NULL, 4, 1, '2026-02-03 15:45:29', '2026-02-03 15:59:11', NULL),
(5, 'ศูนย์อนามัยที่ 9 นครราชสีมา', 'ศูนย์อนามัย 9', 'หน่วยงานในสังกัดกรมอนามัย ดูแลด้านส่งเสริมสุขภาพและอนามัยสิ่งแวดล้อมในเขตสุขภาพที่ 9', '044-305-131', 'hpc9@anamai.mail.go.th', '177 หมู่ 6 ต.โคกกรวด อ.เมือง จ.นครราชสีมา 30280', 'https://hpc9.anamai.moph.go.th', NULL, 5, 1, '2026-02-03 15:45:29', '2026-02-03 15:59:11', NULL),
(6, 'สำนักงานประกันสังคมจังหวัดนครราชสีมา', 'ประกันสังคม', 'หน่วยงานดูแลด้านประกันสังคม สิทธิประโยชน์ และคุ้มครองผู้ประกันตนในจังหวัดนครราชสีมา', '044-213-266', 'nakhonratchasima@sso.go.th', '369/5 ถ.สุรนารี ต.ในเมือง อ.เมือง จ.นครราชสีมา 30000', 'https://www.sso.go.th/wpr/nakhonratchasima', NULL, 6, 1, '2026-02-03 15:45:29', '2026-02-03 15:59:11', NULL),
(7, 'ศูนย์ส่งเสริมอุตสาหกรรมภาคที่ 6', 'ศูนย์อุตฯ ภาค 6', 'หน่วยงานสนับสนุนและพัฒนาอุตสาหกรรมในภาคตะวันออกเฉียงเหนือตอนล่าง', '044-233-404', 'ipc6@dip.go.th', '333 หมู่ 7 ถ.มิตรภาพ ต.หนองไผ่ล้อม อ.เมือง จ.นครราชสีมา 30000', 'https://ipc6.dip.go.th', NULL, 7, 1, '2026-02-03 15:45:29', '2026-02-03 15:59:11', NULL),
(8, 'สำนักงานสวัสดิการและคุ้มครองแรงงานจังหวัดนครราชสีมา', 'สวัสดิการแรงงาน', 'หน่วยงานดูแลด้านสวัสดิการแรงงาน ความปลอดภัยในการทำงาน และคุ้มครองแรงงาน', '044-243-217', 'nakhonratchasima@labour.mail.go.th', 'ศาลากลางจังหวัดนครราชสีมา ชั้น 3 ถ.มหาดไทย ต.ในเมือง อ.เมือง จ.นครราชสีมา 30000', 'https://nakhonratchasima.labour.go.th', NULL, 8, 1, '2026-02-03 15:45:29', '2026-02-03 15:59:11', NULL),
(9, 'ศูนย์ความปลอดภัยในการทำงานเขต 3 (นครราชสีมา)', 'ศูนย์ความปลอดภัย 3', 'หน่วยงานส่งเสริมและพัฒนาความปลอดภัยอาชีวอนามัยในสถานประกอบการ', '044-212-048', 'oshc3@labour.mail.go.th', '204 ถ.มิตรภาพ ต.ในเมือง อ.เมือง จ.นครราชสีมา 30000', 'https://www.oshthai.org', NULL, 9, 1, '2026-02-03 15:45:29', '2026-02-03 15:59:11', NULL),
(10, 'สำนักงานอุตสาหกรรมจังหวัดนครราชสีมา', 'อุตสาหกรรมจังหวัด', 'หน่วยงานดูแลด้านการส่งเสริมอุตสาหกรรม กำกับโรงงาน และพัฒนาผู้ประกอบการ', '044-212-430', 'nakhonratchasima@industry.go.th', 'ศาลากลางจังหวัดนครราชสีมา ชั้น 4 ถ.มหาดไทย ต.ในเมือง อ.เมือง จ.นครราชสีมา 30000', 'https://nakhonratchasima.industry.go.th', NULL, 10, 1, '2026-02-03 15:45:29', '2026-02-03 15:59:11', NULL),
(11, 'ศูนย์สุขภาพจิตที่ 9', 'ศูนย์สุขภาพจิต 9', 'หน่วยงานส่งเสริมสุขภาพจิตและป้องกันปัญหาสุขภาพจิตในเขตสุขภาพที่ 9', '044-256-729', 'mhc9@dmh.mail.go.th', '86 ถ.ช้างเผือก ต.ในเมือง อ.เมือง จ.นครราชสีมา 30000', 'https://mhc9.dmh.go.th', NULL, 11, 1, '2026-02-03 15:45:29', '2026-02-03 15:59:11', NULL),
(12, 'สำนักงานป้องกันควบคุมโรคที่ 9 นครราชสีมา', 'สคร.9', 'หน่วยงานเฝ้าระวัง ป้องกัน และควบคุมโรคในเขตสุขภาพที่ 9', '044-212-900', 'dpc9@ddc.mail.go.th', '168/5 ถ.มิตรภาพ ต.ในเมือง อ.เมือง จ.นครราชสีมา 30000', 'https://dpc9.ddc.moph.go.th', NULL, 12, 1, '2026-02-03 15:45:29', '2026-02-03 15:59:11', NULL),
(13, 'สถาบันพัฒนาฝีมือแรงงาน 5 นครราชสีมา', 'สพร.5', 'หน่วยงานพัฒนาทักษะฝีมือแรงงานและยกระดับมาตรฐานฝีมือ', '044-416-155', 'dsd5@dsd.go.th', '340 หมู่ 3 ถ.มิตรภาพ ต.หนองไข่น้ำ อ.เมือง จ.นครราชสีมา 30310', 'https://www.dsd.go.th/nakhonratchasima', NULL, 13, 1, '2026-02-03 15:45:29', '2026-02-03 15:59:11', NULL),
(14, 'การนิคมอุตสาหกรรมแห่งประเทศไทย', 'กนอ.', 'รัฐวิสาหกิจดูแลนิคมอุตสาหกรรมและเขตประกอบการอุตสาหกรรมทั่วประเทศ', '02-253-0561', 'contact@ieat.go.th', '618 ถ.นิคมมักกะสัน แขวงมักกะสัน เขตราชเทวี กรุงเทพฯ 10400', 'https://www.ieat.go.th', NULL, 14, 1, '2026-02-03 15:45:29', '2026-02-03 15:59:11', NULL),
(15, 'จังหวัดนครราชสีมา', 'จ.นครราชสีมา', 'หน่วยงานราชการส่วนภูมิภาคระดับจังหวัด ดูแลบริหารราชการในพื้นที่', '044-243-798', 'nakhonratchasima@moi.go.th', 'ศาลากลางจังหวัดนครราชสีมา ถ.มหาดไทย ต.ในเมือง อ.เมือง จ.นครราชสีมา 30000', 'https://www.nakhonratchasima.go.th', NULL, 15, 1, '2026-02-03 15:45:29', '2026-02-03 15:59:11', NULL),
(16, 'สภาอุตสาหกรรมแห่งประเทศไทย', 'ส.อ.ท.', 'องค์กรเอกชนด้านอุตสาหกรรม เป็นตัวแทนภาคอุตสาหกรรมในการพัฒนาและแก้ไขปัญหา', '02-345-1000', 'information@fti.or.th', 'ศูนย์การประชุมแห่งชาติสิริกิติ์ โซน C ชั้น 4 เลขที่ 60 ถ.รัชดาภิเษกตัดใหม่ แขวงคลองเตย เขตคลองเตย กรุงเทพฯ 10110', 'https://www.fti.or.th', NULL, 16, 1, '2026-02-03 15:45:29', '2026-02-03 15:59:11', NULL),
(17, 'กระทรวงดิจิทัลเพื่อเศรษฐกิจและสังคม', 'ก.ดิจิทัล', 'กระทรวงดูแลด้านเทคโนโลยีดิจิทัล การพัฒนาเศรษฐกิจและสังคมดิจิทัล', '02-141-6747', 'contact@mdes.go.th', '120 หมู่ 3 อาคารรัฐประศาสนภักดี (อาคาร B) ศูนย์ราชการฯ ถ.แจ้งวัฒนะ แขวงทุ่งสองห้อง เขตหลักสี่ กรุงเทพฯ 10210', 'https://www.mdes.go.th', NULL, 17, 1, '2026-02-03 15:45:29', '2026-02-03 15:59:11', NULL),
(18, 'สภาอุตสาหกรรมจังหวัดนครราชสีมา', 'ส.อ.ท.นครราชสีมา', 'องค์กรเอกชนระดับจังหวัด เป็นตัวแทนภาคอุตสาหกรรมในจังหวัดนครราชสีมา', '044-261-335', 'fti.korat@gmail.com', '2112/11 ถ.มิตรภาพ ต.ในเมือง อ.เมือง จ.นครราชสีมา 30000', 'https://www.fti.or.th/fti-chapter/nakhonratchasima', NULL, 18, 1, '2026-02-03 15:45:29', '2026-02-03 15:59:11', NULL);
INSERT INTO `pillars` (`id`, `code`, `name_th`, `name_en`, `description`, `weight`, `indicators_count`, `color`, `icon`, `display_order`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'H1', 'การส่งเสริมสุขภาพ', 'Health Promotion', 'มุ่งเน้นการสร้างเสริมสุขภาพแบบองค์รวม ครอบคลุมสุขภาพกาย จิต สังคม และปัญญา', 300, 15, '#10B981', 'heart-pulse', 1, 1, '2026-01-30 04:55:20', '2026-01-30 04:55:20'),
(2, 'I2', 'ความปลอดภัยและสิ่งแวดล้อม', 'Industrial Safety &amp; Environment', 'มุ่งเน้นการจัดการความปลอดภัยอาชีวอนามัยและสิ่งแวดล้อมในการทำงาน', 300, 15, '#3b82f6', 'tint', 2, 1, '2026-01-30 04:55:20', '2026-02-07 10:49:12'),
(3, 'C3', 'การมีส่วนร่วมกับชุมชน', 'Community Engagement', 'มุ่งเน้นการสร้างความสัมพันธ์เชิงบวกระหว่างสถานประกอบการกับชุมชนโดยรอบ', 200, 15, '#F59E0B', 'users', 3, 1, '2026-01-30 04:55:20', '2026-01-30 04:55:20'),
(4, 'M4', 'การบริหารจัดการและความยั่งยืน', 'Management &amp; Sustainability', 'มุ่งเน้นการบริหารจัดการองค์กรแบบบูรณาการที่เชื่อมโยงกับกลยุทธ์ระยะยาว', 200, 15, '#8b5cf6', 'chart-bar', 4, 1, '2026-01-30 04:55:20', '2026-02-07 14:23:10');
