(57, 'admin', 'static:manual-database', 'โครงสร้างฐานข้อมูล (Database Schema)', '<!--MANUAL_META:{\"display_category\":\"overview\"}-->\n<table class=\"data-table\">\n                                <thead><tr><th>ตาราง</th><th>หน้าที่</th></tr></thead>\n                                <tbody>\n                                    <tr><td><strong>users</strong></td><td>ผู้ใช้งาน (admin, auditor, company, ceo)</td></tr>\n                                    <tr><td><strong>companies</strong></td><td>ข้อมูลสถานประกอบการ</td></tr>\n                                    <tr><td><strong>assessment_periods</strong></td><td>รอบการประเมิน</td></tr>\n                                    <tr><td><strong>pillars</strong></td><td>4 Pillars HICM</td></tr>\n                                    <tr><td><strong>indicators</strong></td><td>ตัวชี้วัด 60 ข้อ</td></tr>\n                                    <tr><td><strong>assessments</strong></td><td>การประเมินแต่ละบริษัท/รอบ</td></tr>\n                                    <tr><td><strong>assessment_scores</strong></td><td>คะแนนรายตัวชี้วัด (self + auditor)</td></tr>\n                                    <tr><td><strong>attachments</strong></td><td>ไฟล์แนบหลักฐาน</td></tr>\n                                    <tr><td><strong>assessment_logs</strong></td><td>ประวัติการทำงาน</td></tr>\n                                    <tr><td><strong>notifications</strong></td><td>การแจ้งเตือน</td></tr>\n                                </tbody>\n                            </table>', 220, 1, '2026-04-27 21:15:28', '2026-04-27 21:15:28'),
(58, 'admin', 'static:manual-api', 'API Endpoints', '<!--MANUAL_META:{\"display_category\":\"overview\"}-->\n<table class=\"data-table\">\n                                <thead><tr><th>Endpoint</th><th>หน้าที่</th></tr></thead>\n                                <tbody>\n                                    <tr><td>upload.php</td><td>อัปโหลดไฟล์หลักฐาน</td></tr>\n                                    <tr><td>download.php</td><td>ดาวน์โหลดไฟล์แนบ</td></tr>\n                                    <tr><td>get_attachments.php</td><td>ดึงรายการไฟล์แนบ</td></tr>\n                                    <tr><td>save-assessment.php</td><td>บันทึกการประเมินตนเอง</td></tr>\n                                    <tr><td>save-auditor-score.php</td><td>บันทึกคะแนนกรรมการ</td></tr>\n                                    <tr><td>submit-auditor-evaluation.php</td><td>ส่งผลการประเมินกรรมการ</td></tr>\n                                    <tr><td>export-excel.php</td><td>ส่งออก Excel</td></tr>\n                                </tbody>\n                            </table>', 230, 1, '2026-04-27 21:15:28', '2026-04-27 21:15:28'),
(59, 'admin', 'static:manual-formulas', 'สูตรการคำนวณคะแนน (Scoring Mechanics)', '<!--MANUAL_META:{\"display_category\":\"overview\"}-->\n<div class=\"manual-content-rendered\">\n                                <h3>1. คะแนนรายเสาหลัก (Pillar Score)</h3>\n                                <p>คำนวณจากค่าเฉลี่ยของตัวชี้วัดที่ประเมิน (ไม่รวม N/A) คูณด้วยน้ำหนักของเสาหลักนั้นๆ</p>\n                                <div style=\"background:#f1f5f9; padding:1.5rem; border-radius:0.75rem; border-left:4px solid var(--manual-primary); font-family:monospace; margin:1rem 0;\">\n                                    Pillar Score = (Σ Indicator Scores / Count of Evaluated) × Pillar Weight\n                                </div>\n                            </div>', 240, 1, '2026-04-27 21:15:28', '2026-04-27 21:15:28'),
(60, '', 'static:manual-pillars', '4 Pillars & ระดับคะแนน', '<!--MANUAL_META:{\"display_category\":\"overview\"}-->\n<h3 class=\"text-lg font-bold mb-3\">โครงสร้าง 4 Pillars</h3>\n                            <table class=\"data-table mb-4\">\n                                <thead><tr><th>Pillar</th><th>ชื่อ</th><th>จำนวนตัวชี้วัด</th><th>น้ำหนัก (คะแนน)</th></tr></thead>\n                                <tbody>\n                                                                        <tr><td><strong>H1</strong></td><td>การส่งเสริมสุขภาพ</td><td>15</td><td>300</td></tr>\n                                                                        <tr><td><strong>I2</strong></td><td>ความปลอดภัยและสิ่งแวดล้อม</td><td>15</td><td>300</td></tr>\n                                                                        <tr><td><strong>C3</strong></td><td>การมีส่วนร่วมกับชุมชน</td><td>15</td><td>200</td></tr>\n                                                                        <tr><td><strong>M4</strong></td><td>การบริหารจัดการและความยั่งยืน</td><td>15</td><td>200</td></tr>\n                                                                        <tr style=\"font-weight:700; background:#f8fafc;\"><td colspan=\"2\">รวม</td><td>60</td><td>1,000</td></tr>\n                                </tbody>\n                            </table>\n                            <h3 class=\"text-lg font-bold mb-3 mt-4\">ระดับการรับรอง HICM</h3>\n                            <table class=\"data-table\">\n                                <thead><tr><th>ระดับ</th><th>คะแนน</th><th>ชื่อ</th></tr></thead>\n                                <tbody>\n                                                                        <tr>\n                                        <td><strong>Level 1</strong></td>\n                                        <td>0–599</td>\n                                        <td>เริ่มต้น</td>\n                                    </tr>\n                                                                        <tr>\n                                        <td><strong>Level 2</strong></td>\n                                        <td>600–699</td>\n                                        <td>กำลังพัฒนา</td>\n                                    </tr>\n                                                                        <tr>\n                                        <td><strong>Level 3</strong></td>\n                                        <td>700–799</td>\n                                        <td>พัฒนาดี</td>\n                                    </tr>\n                                                                        <tr>\n                                        <td><strong>Level 4</strong></td>\n                                        <td>800–899</td>\n                                        <td>เป็นเลิศ</td>\n                                    </tr>\n                                                                        <tr>\n                                        <td><strong>Level 5</strong></td>\n                                        <td>900–1000</td>\n                                        <td>ระดับโลก</td>\n                                    </tr>\n                                                                    </tbody>\n                            </table>', 250, 1, '2026-04-27 21:15:28', '2026-04-27 21:15:28');
INSERT INTO `user_manual` (`id`, `role`, `category`, `title`, `content`, `display_order`, `is_active`, `created_at`, `updated_at`) VALUES
(61, '', 'static:manual-personas', 'ตัวละคร (Personas)', '<!--MANUAL_META:{\"display_category\":\"usage\"}-->\n<div class=\"persona-grid\" style=\"display:grid; grid-template-columns:repeat(auto-fit, minmax(280px, 1fr)); gap:1.5rem;\">\n                                <div class=\"persona-card\" style=\"padding:1.5rem; border:1px solid #e2e8f0; border-radius:1rem; background:#fff;\">\n                                    <div class=\"persona-header\" style=\"display:flex; align-items:center; gap:1rem; margin-bottom:1rem;\">\n                                        <div style=\"width:48px; height:48px; background:#3b82f6; border-radius:50%; display:flex; align-items:center; justify-content:center; color:#fff; font-weight:bold;\">A</div>\n                                        <div><div style=\"font-weight:bold;\">Admin</div><div style=\"font-size:0.85rem; color:#64748b;\">ผู้ดูแลระบบ</div></div>\n                                    </div>\n                                    <p style=\"font-size:0.9rem; color:#475569;\">จัดการระบบ ตั้งค่าตัวชี้วัด และดูแลผู้ใช้</p>\n                                </div>\n                                <div class=\"persona-card\" style=\"padding:1.5rem; border:1px solid #e2e8f0; border-radius:1rem; background:#fff;\">\n                                    <div class=\"persona-header\" style=\"display:flex; align-items:center; gap:1rem; margin-bottom:1rem;\">\n                                        <div style=\"width:48px; height:48px; background:#10b981; border-radius:50%; display:flex; align-items:center; justify-content:center; color:#fff; font-weight:bold;\">B</div>\n                                        <div><div style=\"font-weight:bold;\">Auditor</div><div style=\"font-size:0.85rem; color:#64748b;\">กรรมการ</div></div>\n                                    </div>\n                                    <p style=\"font-size:0.9rem; color:#475569;\">ตรวจประเมิน ให้คะแนน และให้ข้อเสนอแนะ</p>\n                                </div>\n                                <div class=\"persona-card\" style=\"padding:1.5rem; border:1px solid #e2e8f0; border-radius:1rem; background:#fff;\">\n                                    <div class=\"persona-header\" style=\"display:flex; align-items:center; gap:1rem; margin-bottom:1rem;\">\n                                        <div style=\"width:48px; height:48px; background:#f59e0b; border-radius:50%; display:flex; align-items:center; justify-content:center; color:#fff; font-weight:bold;\">C</div>\n                                        <div><div style=\"font-weight:bold;\">Company</div><div style=\"font-size:0.85rem; color:#64748b;\">สถานประกอบการ</div></div>\n                                    </div>\n                                    <p style=\"font-size:0.9rem; color:#475569;\">ประเมินตนเอง แนบหลักฐาน และติดตามผล</p>\n                                </div>\n                            </div>', 260, 1, '2026-04-27 21:15:28', '2026-04-27 21:15:28'),
(62, '', 'static:manual-status', 'สถานะการประเมิน (Status Flow)', '<!--MANUAL_META:{\"display_category\":\"usage\"}-->\n<div class=\"flow-diagram\">\n                                <pre class=\"mermaid\" style=\"background:transparent;\" data-processed=\"true\"><svg id=\"mermaid-1777299317610\" width=\"100%\" xmlns=\"http://www.w3.org/2000/svg\" xmlns:xlink=\"http://www.w3.org/1999/xlink\" class=\"statediagram\" style=\"max-width: 137.46665954589844px;\" viewBox=\"0 0 137.46665954589844 610.9998779296875\" role=\"graphics-document document\" aria-roledescription=\"stateDiagram\"><style>#mermaid-1777299317610{font-family:\"trebuchet ms\",verdana,arial,sans-serif;font-size:16px;fill:#000000;}#mermaid-1777299317610 .error-icon{fill:#552222;}#mermaid-1777299317610 .error-text{fill:#552222;stroke:#552222;}#mermaid-1777299317610 .edge-thickness-normal{stroke-width:2px;}#mermaid-1777299317610 .edge-thickness-thick{stroke-width:3.5px;}#mermaid-1777299317610 .edge-pattern-solid{stroke-dasharray:0;}#mermaid-1777299317610 .edge-pattern-dashed{stroke-dasharray:3;}#mermaid-1777299317610 .edge-pattern-dotted{stroke-dasharray:2;}#mermaid-1777299317610 .marker{fill:#666;stroke:#666;}#mermaid-1777299317610 .marker.cross{stroke:#666;}#mermaid-1777299317610 svg{font-family:\"trebuchet ms\",verdana,arial,sans-serif;font-size:16px;}#mermaid-1777299317610 defs #statediagram-barbEnd{fill:#000;stroke:#000;}#mermaid-1777299317610 g.stateGroup text{fill:#999;stroke:none;font-size:10px;}#mermaid-1777299317610 g.stateGroup text{fill:#000000;stroke:none;font-size:10px;}#mermaid-1777299317610 g.stateGroup .state-title{font-weight:bolder;fill:#111111;}#mermaid-1777299317610 g.stateGroup rect{fill:#eee;stroke:#999;}#mermaid-1777299317610 g.stateGroup line{stroke:#666;stroke-width:1;}#mermaid-1777299317610 .transition{stroke:#000;stroke-width:1;fill:none;}#mermaid-1777299317610 .stateGroup .composit{fill:#ffffff;border-bottom:1px;}#mermaid-1777299317610 .stateGroup .alt-composit{fill:#e0e0e0;borde